Finally, we obtain the partition function for the triangular system as
\begin{align}
	Z_0 &= 2^{N_s} (1 - t^2)^{-\frac{3N_s}{2}} \left(1+t\right)^{N_s}  \times \nonumber\\
	& \quad \prod_{k_x,k_y=0}^{L} \left\{ \left(t^4 - 2t^3 + 6t^2 - 2t + 1 \right) - 2t \left(1-t \right)^2 \left[ \cos\left(\frac{2\pi k_x}{L}\right) + \cos\left(\frac{2\pi k_y}{L}\right) + \cos\left(\frac{2\pi k_x+ 2\pi k_y}{L}\right) \right] \right\}^{1/2}, 
    \label{PartitionFunction0}
\end{align}
where we used that $N_b = 3 N_s$ for the triangular lattice.
%, since each site was connected by six bonds, and each two sites share one bond.
The free energy of the system can be obtained from the partition
function~\eqref{PartitionFunction0}, which gives
\begin{align}
    F_0 = & -T \ln Z \nonumber\\
    = & -N_sT\ln 2 + \frac{3N_s}{2}T \ln (1 - t^2) - N_sT\ln (1 + t) \nonumber\\
    &- \frac{1}{2} T \sum_{k_x,k_y=0}^{L} 
    \ln \left\{ \left(t^4 - 2t^3 + 6t^2 - 2t + 1 \right) - 2t \left(1-t \right)^2 \left[ \cos\left(\frac{2\pi k_x}{L}\right) + \cos\left(\frac{2\pi k_y}{L}\right) + \cos\left(\frac{2\pi k_x+ 2\pi k_y}{L}\right) \right] \right\}. \label{F0sum}
\end{align}
In the thermodynamic limit ($L \rightarrow \infty$), the sum
in Eq.~\eqref{F0sum} can be replaced by an integral:
\begin{align}
	F_0  = -N_sT\ln 2  + \frac{3N_s}{2}T \ln (1 - t^2) -N_sT\ln (1 + t) -\frac{N_sT}{2 (2\pi)^2} \int_0^{2\pi} \int_0^{2\pi} 
	\ln P \, d\omega_1 \, d\omega_2, 
    \label{freeEn}
\end{align}
where $P =  \left(t^4 - 2t^3 + 6t^2 - 2t + 1 \right) - 2t \bigl(1-t \bigr)^2 \omega$
and $ \omega = \left[\cos\omega_1 + \cos\omega_2 + \cos\left(\omega_1 + \omega_2\right) \right]$.


The free energy can be expanded in the small exponential $e^{-\frac{2J}{T}}$ as
% To expand the free energy at low temperature up to  $O\left(e^{-\frac{6J}{T}} \right)$,
\begin{align}
	F_0  =& N_sT\ln 2  - N_s J -2N_s Te^{-\frac{2J}{T}} + N_s Te^{-\frac{4J}{T}}
	\nonumber \\
		& + 2N_s Te^{-\frac{2J}{T}} -N_s T \ln2 -\frac{N_s T}{8 \pi^2} \int_0^{2\pi} \int_0^{2\pi} \left[ \ln\left(3 + 2 \omega\right) + 2\frac{3+\omega}{3+2\omega} e^{-\frac{4J}{T}} \right] \, d\omega_1 \, d\omega_2 + O\left(e^{-\frac{6J}{T}} \right)
	\nonumber \\
	= & - N_s J - N_sT I_S + \left(1 - I_0\right) N_s T e^{-\frac{4J}{T}}
	 + O\left(e^{-\frac{6J}{T}} \right),
\end{align}
where we have defined % $I_0$ and $I_S$ as
\begin{align}
	I_0  & \equiv  \frac{1}{4 \pi^2} \int_0^{2\pi} \int_0^{2\pi} 
    \frac{3+\omega}{3+2\omega}  \, d\omega_1 \, d\omega_2
	=  5.191389\ldots,
    \label{I0}
\end{align}
 and 
\begin{align}
	I_S  \equiv & \frac{1}{8 \pi^2} \int_0^{2\pi} \int_0^{2\pi} 
     \ln\left(3 + 2 \omega\right)   \, d\omega_1 \, d\omega_2 
	=  0.323066\ldots.
\end{align}
In what follows, we will see that $I_S$ gives the entropy of the system per spin at zero
temperature.
%\tr{$I_S$ is defined here but is not used in the above equation. It has to be defined on first use.} 


Utilising Eq.~\eqref{freeEn}, we obtain the entropy of the system per spin:
%The entropy per spin in the system can be derived from the free energy Eq.~\eqref{freeEn},
\begin{align}
	S_0(T) = & -\frac{1}{N_s}\frac{\partial F_0}{\partial T} \nonumber\\
	= & \ln 2 -\frac{3}{2}\left[\ln\left(1-t^2\right) - \frac{2Jt}{T}\right] +\left[\ln(1+t) + \frac{\left(1-t\right)J}{T}\right]
	+ \frac{1}{8\pi^2} \int_0^{2\pi} \int_0^{2\pi} \left( \ln P + T\,\frac{1}{P}\frac{\partial P}{\partial t}\frac{dt}{dT} \right) d\omega_1 \, d\omega_2. \label{entropy}
\end{align}

%To expand the entropy at low temperature and keep up to $O\left(e^{-\frac{6J}{T}} \right)$,

Expanding the above entropy $S_0(T)$ in the small exponential $e^{-\frac{2J}{T}}$ gives
\begin{align}
	S_0(T) = & -\ln2 + \frac{1}{8\pi^2}\int_0^{2\pi}\int_0^{2\pi}\ln\left(12+8\omega\right)d\omega_1\,d\omega_2
	\nonumber \\
	&+\left[ \left( 2 + \frac{4J}{T} \right)
	-\frac{1}{8\pi^2}\int_0^{2\pi}\int_0^{2\pi}\left( 4 + \frac{8J}{T} \right)d\omega_1\,d\omega_2\right]e^{-\frac{2J}{T}}
	\nonumber \\
	&+ \left( 1 + \frac{4J}{T} \right) e^{-\frac{4J}{T}} \left(\frac{1}{4\pi^2}\int_0^{2\pi}\int_0^{2\pi} \frac{3 + \omega}{3 + 2\omega}d\omega_1\,d\omega_2  -1\right)
	+O\left(e^{-\frac{6J}{T}} \right) 
	\nonumber \\
	 = & I_S + \left(I_0 - 1\right) \left( 1 + \frac{4J}{T} \right)  e^{-\frac{4J}{T}} + O\left(e^{-\frac{6J}{T}} \right). 
     \label{entropy_1}
\end{align}

The zero-point entropy is given by
%\tr{Why does it say ``for the antiferromagnetic case''? We have already been implying $J>0$
%when expanding in the small exponential $e^{-\frac{2J}{T}}$. Besides, we do not provide any results for the ferromagnetic case (which is fine)}
\begin{align}
	S_0(0) &= I_S = \frac{1}{8\pi^2} \int_0^{2\pi} \int_0^{2\pi} \ln \left\{3 + 2\left[\cos\omega_1 + \cos\omega_2 + \cos\left(\omega_1 + \omega_2\right)\right]\right\} \, d\omega_1 \, d\omega_2 \nonumber\\
	&= \frac{1}{8\pi^2} \int_0^{2\pi} \int_0^{2\pi} \ln \left[ 1 + 4 \cos\left(\frac{\omega_1 + \omega_2}{2}\right)\cos\left(\frac{\omega_1 - \omega_2}{2}\right) + 4\cos^2\left(\frac{\omega_1 + \omega_2}{2}\right) \right] \, d\omega_1 \, d\omega_2 \nonumber\\
	&= \frac{1}{8\pi^2} \int_0^{2\pi} \int_0^{2\pi} \ln \left( 1 - 4 \cos \omega \cos\omega' + 4\cos^2\omega' \right) \, d\omega \, d\omega' \nonumber\\
	&\approx  0.323066\ldots. 
    \label{ZeroTemperatureEntropyNoVacancy}
\end{align}
The value of the entropy~\eqref{ZeroTemperatureEntropyNoVacancy}
matches the result obtained by Wannier~\cite{Wannier:Ising,Wannier:erratum}
using a different method.


The heat capacity per site is given by %can be derived by using $T\partial_TS_0(T)$ from Eq.~\eqref{entropy}. 
\begin{align}
	C_0(T) = T\partial_TS_0(T) &= 3\left(\frac{T\,t}{1-t^2}\frac{dt}{dT}+J\,\frac{dt}{dT}-\frac{J\,t}{T}\right)
	+\frac{T}{1+t}\frac{dt}{dT}-J\,\frac{dt}{dT}-\frac{J(1-t)}{T}
	\nonumber \\
	&\quad+\frac{T}{8\pi^2}\int_0^{2\pi}\int_0^{2\pi}\left\{\frac{2}{P}\frac{\partial P}{\partial t}\frac{dt}{dT}
	+ T\left[\frac{P\,\frac{\partial^2 P}{\partial t^2}-\left(\frac{\partial P}{\partial t}\right)^2}{P^2}\left(\frac{dt}{dT}\right)^2
	+\frac{1}{P}\frac{\partial P}{\partial t}\frac{d^2t}{dT^2}\right]\right\}d\omega_1\,d\omega_2\,. 
\end{align}

Expanding the heat capacity $C_0(T)$ in the small parameter $e^{-\frac{2J}{T}}$
gives
% One can expand the integral and non-integral part of the above heat capacity up to $O\left(e^{-\frac{6J}{T}} \right)$,
\begin{align}
	C_0(T) =& \frac{8J^2}{T^2}\,e^{-2\frac{J}{T}} -\frac{16J^2}{T^2}e^{-\frac{4J}{T}}
         +\frac{1}{8\pi^2}\int_0^{2\pi}\int_0^{2\pi} \left[-\frac{16 J^2 }{T^2} e^{-\frac{2J}{T}} + \frac{32 J^2\left( 3 + \omega \right) }{T^2 (3 + 2\omega)} e^{-\frac{4J}{T}} \right] d\omega_1\,d\omega_2\, + O \left( e^{-\frac{6J}{T}} \right)
         \nonumber \\
         =& \frac{16J^2}{T^2} (I_0 - 1) e^{-\frac{4J}{T}}  + O \left(e^{-\frac{6J}{T}}  \right),
         \label{CleanCAppendix}
\end{align}
%\tr{Please put brackets around the integrand}
where the constant $I_0$ is defined by Eq.~\eqref{I0}.


