\section{Thermodynamics of the system with a single vacancy}

%\tr{I think some notations still need to be brought to the form consistent with the
%main text}

In this section, we compute the contribution of a single vacancy defect to the partition function following the approach described in Sec.~\ref{SuppSec:vacancy-free}. We will denote the quantities of the system with vacancy with the subscript $1$. Assuming there's a vacancy at site $\brho_0$ and using Eqs.~(\ref{eq:Z_in_R}-\ref{eq:R_0}), 
the partition function of the Ising spins on an arbitrary lattice with a single vacancy defect can be 
written as
\begin{align}
\label{eq:Z1_all}
    Z_1=2^{N_s-1}\left(1-t^2\right)^{-(N_b-z)/2}\exp\left(-\sum_{r=1}^{\infty}t^rf_{1;r}\right),
\end{align}
where $f_{1;r}$ is the sum over all loops of length $r$ that do not include the site $\brho_0$,
and the variable $t$ is defined by Eq.~\eqref{tDefinition}.

Equation~\eqref{eq:Z1_all} reflects that the vacancy 
reduces the number of sites by $1$ and the number of bonds 
by the coordination number $z$.
The sum $f_{1;r}$ is given by the difference $f_{1;r}=f_r-\tilde{f}_r(\brho_0)$
of the sum $f_r$ over all loops of length $r$ and the sum $\tilde{f}_r(\brho_0)$ over the loops
of length $r$ not containing the site $\brho_0$. Averaging over the location of the vacancy gives 
\begin{align}
    \frac{1}{N_s}\sum_{\brho_0}\tilde{f}_r(\brho_0)=\frac{r}{N_s}f_r,
\end{align}
where we used that $\sum_{\brho_0}\tilde{f}_r(\brho_0) = r f_r$,
%\tr{What are $a$ and $b$ here? If those are the coordinates of $\brho_0$, 
%why not just write summation wrt $\brho_0$?}
considering that each loop that contributes to the sum has $r$ sites.
% because that is the sum over all loops of length $r$ containing the site $\brho_0$ for all the points in the system. Thus, each loop of length $r$ is repeated $r$ times corresponding to the number of points on the loop.
% Since the number of loops passing by a point should be independent of that point due to the lattice translational symmetry, we conclude that 
Utilising that
\begin{align}
        f_{1;r}=f_r-\frac{r}{N_s}f_r,
\end{align}
%Plugging the above expression into Eq.~(\ref{eq:Z1_all}) and using Eqs.~(\ref{eq:Z_in_R}-\ref{eq:R_0}) to recognize the partition function of the vacancy free system, we find 
the partition function of the system with a vacancy defect can be rewritten in the form
\begin{align}
    \label{eq:Z1_Zvac}
    Z_1=Z_0\left[\frac{1}{2}\left(1-t^2\right)^{z/2}\exp\left(\frac{1}{N_s}\sum_{r=1}^{\infty}rt^rf_r\right)\right]\equiv Z_0 Z_{\vac}.
\end{align}

The sum of the series in Eq.~\eqref{eq:Z1_Zvac} can be reduced to the 
previously computed sum by differentiating with respect to $t$:
$\sum_{r=1}^{\infty}rt^rf_r=t\partial_t\left(\sum_{r=1}^{\infty}t^rf_r\right)$, which gives
\begin{align}
     \label{eq:Zvac}
    Z_\vac=\left\{\frac{1}{2}\left(1-t^2\right)^{z/2}\exp\left[\frac{t}{N_s}\frac{\partial}{\partial t}\left(\sum_{r=1}^{\infty}t^rf_r\right)\right]\right\}.
\end{align}
Equation~\eqref{eq:Zvac} describes the partition function of a vacancy
defect in a generic lattice. In what follows, we explicitly compute 
this function for a triangular lattice.



The sum $\sum_{r=1}^{\infty}t^rf_r$ has been computed in 
Sec.~\ref{SuppSec:vacancy-free} and is given by Eqs.~\eqref{eq:R_0}
and \eqref{eq:R_prod}:
% For the triangular lattice in particular, the $\sum_{r=1}^{\infty}t^rf_r$ is derived in Sec.~\ref{SuppSec:vacancy-free} and can be read from Eqs.~(\ref{eq:R_0},\ref{eq:R_prod}) to be 
\begin{align}
    &\sum_{r=1}^{\infty}t^rf_r=
    \nonumber\\
    &-N_s \ln(1+t)-\frac{1}{2}\sum_{k_x,k_y=0}^{L}\ln 
	\left\{ \left(t^4 - 2t^3 + 6t^2 - 2t + 1 \right) - 2t \left(1-t \right)^2 \left[ \cos\left(\frac{2\pi k_x}{L}\right) + \cos\left(\frac{2\pi k_y}{L}\right) + \cos\left(\frac{2\pi k_x+ 2\pi k_y}{L}\right) \right] \right\}.
    \label{SumForVacancy}
\end{align}


Utilising Eqs.~\eqref{eq:Zvac} and \eqref{SumForVacancy}, we arrive at the free energy
$F_\vac=F_1-F_0$ associated with the vacancy defect:
\begin{align}
    F_{\vac}=T\ln(2)-3T\ln(1-t^2)+\frac{Tt}{1+t}+\frac{T}{2(2\pi)^2}\int_0^{2\pi}\int_0^{2\pi}\frac{t\partial_tP(t,\omega_1,\omega_2)}{P(t,\omega_1,\omega_2)}\mathrm{d}\omega_1\mathrm{d}\omega_2. \label{Eq:Fvac}
\end{align}


In the limit of low temperatures $T\ll J$, the variable $t$ can be approximated as
$t\equiv -\tanh\left(J/T\right)\approx (-1)\left(1-2e^{-2J/T}+2e^{-4J/T}\right)+O(e^{-6J/T})$
and the free energy $F_\vac$ of the vacancy defect can be expanded in the 
powers of the small exponential $e^{-\frac{2J}{T}}\ll 1$ as
\begin{align}
    F_\vac= -\frac{1}{2}Te^{\frac{2J}{T}}+6J-T\left[5\ln(2)-\frac{3}{2}\right]+\left(6-I_0\right)Te^{-\frac{2J}{T}}+3Te^{-\frac{4J}{T}}+O\left(e^{-\frac{6J}{T}}\right).
    \label{FreeEnergyExpanded}
\end{align}
The leading temperature dependence in Eq.~\eqref{FreeEnergyExpanded}, given by the first term, shows exponential 
dependence of the free energy associated with the vacancy defect, on temperature. Qualitatively, this dependence is explained in the main text.

The contribution $S_\vac=S_1-S_0=-\partial_T F_{\vac}$ of the vacancy defect to the entropy is given by
\begin{align}
    S_{\vac}=&-\ln(2)+3\left[\ln(1-t^2)-\frac{2Jt}{T}\right]-\frac{t}{1+t}-\frac{J(1-t)}{T(1+t)}\notag\\
    & -\frac{1}{2}\int_0^{2\pi}\int_0^{2\pi}\left\{\frac{t\partial_tP(t,\omega_1,\omega_2)}{P(t,\omega_1,\omega_2)}+\frac{J(1-t^2)}{T}\frac{\partial}{\partial t}\left[\frac{t\partial_tP(t,\omega_1,\omega_2)}{P(t,\omega_1,\omega_2)}\right]\right\}\mathrm{d}\omega_1\mathrm{d}\omega_2.
\end{align}
In the limit of low temperatures $T\ll J$,
the entropy associated with the vacancy is given by
\begin{align}
     S_{\vac}= \frac{1}{2}\left(1-\frac{2J}{T}\right)e^{\frac{2J}{T}}+5\ln(2)-\frac{3}{2}-\left(6-I_0\right)\left(1+\frac{2J}{T}\right)e^{-\frac{2J}{T}}+3\left(1+\frac{4J}{T}\right) e^{-\frac{4J}{T}}+O\left(e^{-\frac{6J}{T}}\right).
     \label{eqn:Svac_low_T}
\end{align}
The vacancy contribution $C_\vac=C_1-C_0$ to the heat capacity is given by
\begin{align}
      C_{\vac}=T\partial_TS_{\vac}(T)
      =\frac{2J^2}{T^2}\left[e^{\frac{2J}{T}}-2\left(6-I_0\right)e^{-\frac{2J}{T}}+24e^{-\frac{4J}{T}}\right]+O\left(e^{-\frac{6J}{T}}\right).
\end{align}



