\section{Thermodynamics of the system with dilute vacancies}

In a system with dilute vacancy defects density $n_{\text{imp}}=N_{\vac}/N\ll \xi^{-2}$, where $\xi$ is the correlation length, the 
interplay of different vacancies can be neglected due to the large typical
distance between the vacancies.
In this regime, the contributions of vacancy defects
to the entropy and the free energy are additive.
At low temperatures $T\ll J$,  
\begin{align}
    \frac{F}{N_s}=\frac{1}{N_s}F_0+n_{\text{imp}} F_\vac&= -J- T I_S + \left(1 - I_0\right) T e^{-\frac{4J}{T}}\notag\\
    &\quad +n_{\text{imp}} \left\{6J-\frac{1}{2}Te^{\frac{2J}{T}}-T\left[5\ln(2)-\frac{3}{2}\right]+\left(6-I_0\right)Te^{-\frac{2J}{T}}+3Te^{-\frac{4J}{T}}\right\}+O\left(e^{-\frac{6J}{T}}\right).
    % -\frac{n_{\text{imp}}}{2}Te^{\frac{2J}{T}} -(1-6n_{\text{imp}})J  - \left[I_S-5\ln(2)n_{\text{imp}}-\frac{3}{2}n_{\text{imp}}\right]T+n_{\text{imp}}\left(6-I_0\right)Te^{-\frac{2J}{T}}\notag\\
    % &\quad \quad +(1-I_0 +3n_{\text{imp}})T e^{-\frac{4J}{T}}+O\left(Te^{-\frac{6J}{T}}\right).
\end{align}


The corresponding entropy is given by
\begin{align}
    S=&I_S + \left(I_0 - 1\right) \left( 1 + \frac{4J}{T} \right)  e^{-\frac{4J}{T}}\notag\\
    & +n_{\text{imp}}\left[\frac{1}{2}\left(1-\frac{2J}{T}\right)e^{\frac{2J}{T}}+5\ln(2)-\frac{3}{2}-\left(6-I_0\right)\left(1+\frac{2J}{T}\right)e^{-\frac{2J}{T}}+3\left(1+\frac{4J}{T}\right) e^{-\frac{4J}{T}}\right]+O\left(e^{-\frac{6J}{T}}\right).
    % \frac{n_{\text{imp}}}{2}\left(1-\frac{2J}{T}\right)e^{\frac{2J}{T}} +\left[I_S-5\ln(2)n_{\text{imp}}-\frac{3}{2}n_{\text{imp}}\right]-\left(6-I_0\right)n_{\text{imp}}\left(1+\frac{2J}{T}\right)e^{-\frac{2J}{T}}\notag\\
    % &\quad \quad+ \left(I_0 - 1+3 n_{\text{imp}}\right) \left( 1 + \frac{4J}{T} \right)  e^{-\frac{4J}{T}} +O\left(e^{-\frac{6J}{T}} \right).
\end{align}
Finally, the heat capacity of the system with dilute vacancy defects
is given by 
\begin{align}
    C=\frac{2J^2}{T^2}\left\{8 (I_0 - 1) e^{-\frac{4J}{T}}+n_{\text{imp}}\left[e^{\frac{2J}{T}} -2\left(6-I_0\right)e^{-\frac{2J}{T}} +24e^{-\frac{4J}{T}}\right]\right\}+ O\left(e^{-\frac{6J}{T}}  \right).
    \label{FullCLong}
\end{align}
The term $\propto e^{-\frac{4J}{T}}$ in Eq.~\eqref{FullCLong} describes the thermodynamics of the clean system. The activation gap $4J$ 
of the exponential temperature dependence matches the lowest excitation energy in such a system, as discussed in Sec.~\ref{SuppSec:vacancy-free}.
The exponentially growing term $\propto n_\text{imp}e^\frac{2J}{T}$
describes the contribution of the vacancies to the heat capacity.
The heat capacity of the vacancies is of the order of the heat capacity
of the clean system at the temperature $T_\text{imp}=-\frac{6J}{\ln{n_\text{imp}}}$.



