\section{Universal property of framed $G$-disc algebras}


\subsection{$G$-approximations to $G$-$\infty$-operads}

In this section we will present the theory of $G$-approximations to $G$-$\infty$-operads. Informally, a $G$-approximation to a $G$-$\infty$-operad is an $\infty$-category that somewhat behaves as a $G$-$\infty$-operad. It is a more general object that can capture information about the original $G$-$\infty$-operad.

\begin{definition}
\label{defgapprox}
Let $p:E^{\otimes}\rightarrow\FinG$ be a $G$-$\infty$-operad and let $f:C\rightarrow E^{\otimes}$ be a categorical fibration. We say that $f$ is a \emph{$G$-approximation} to $E^{\otimes}$ if it satisfies the following conditions:
\begin{enumerate}
\item Let $p'=p\circ f$. The $\infty$-category $C_{I(-)}$ obtained as the pullback
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
C_{I(-)} \arrow[d]\arrow[r] & C \arrow[d,"p' "] \\
\OG^{\op} \arrow[r] & \FinG
\end{tikzcd}
\end{center}
together with the map $C_{I(-)}\rightarrow \OG^{\op}$ is a $G$-$\infty$-category i.e. this map is a coCartesian fibration.

\item Let $c\in C$ and let $p'(c) = I = [U\rightarrow O]$. Then there exists a $p'$-coCartesian morphism $c\rightarrow c_W$ in $C$ lifting $\chi_{W\subseteq U}: I\rightarrow I(W)$ for every $W\in \Orbit(U)$. Additionally, the map $f(c\rightarrow c_W)$ is an inert map in $E^{\otimes}$.

\item Let $c\in C$ and let $\alpha: x\rightarrow f(c)$ be an active morphism in $E^{\otimes}$. Then there exists a Cartesian lift $\bar{\alpha}: \bar{x}\rightarrow c$ of $\alpha$ in $C$.
\end{enumerate}
\end{definition}



\begin{definition}
Let $p:E^{\otimes}\rightarrow\FinG$ and $q:E'^{\otimes}\rightarrow\FinG$ be two $G$-$\infty$-operads and let $f:C\rightarrow E^{\otimes}$ be a $G$-approximation. Denote with $p' = p\circ f$ and consider a functor $F:C\rightarrow E'^{\otimes}$. We will say that $F$ is a \emph{$C$-algebra object} in $E'^{\otimes}$ if the following conditions are satisfied:
\begin{itemize}
\item $F$ induces a $G$-functor between the underlying $G$-$\infty$-categories $C_{I(-)}\rightarrow E'$.
\item The following diagram is commutative
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
C \arrow[d,"f"]\arrow[r,"F"] & E'^{\otimes} \arrow[d,"q"] \\
E^{\otimes} \arrow[r,"p"] & \FinG
\end{tikzcd}
\end{center}
\item Let $x\in C$ and let $p'(x) = [U\rightarrow O]$. Let $\alpha_W : x\rightarrow x_W$ be a $p'$-coCartesian arrow lifting $\chi: [U\rightarrow O] \rightarrow [W\xrightarrow{=}W]$ for $W\in \Orbit(U)$. Then the map $F(\alpha_W)$ is an inert map in $E'^{\otimes}$.
\end{itemize}
We will denote with $\Alg_G(C,E')$ the $\infty$-category of $C$-algebra objects in $E'^{\otimes}$.
\end{definition}
We would like to prove the proposition \ref{ha23323} (the equivariant version of \cite[2.3.3.23]{HA}). The following lemmas will be helpful:
\begin{lemma}
\label{gopinert}
Let $p:E^{\otimes}\rightarrow\FinG$ and $q:E'^{\otimes}\rightarrow\FinG$ be two $G$-$\infty$-operads and let $F:E^{\otimes}\rightarrow E'^{\otimes}$ be a map over $\FinG$. Let $\mathcal{F}$ be a class of arrows in $\FinG$ of type
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U \arrow[d] & O_2 \arrow[l]\arrow[r,"="]\arrow[d,"="] & O_2 \arrow[d,"="] \\
O_1 & O_2 \arrow[l]\arrow[r,"="] & O_2
\end{tikzcd}
\end{center}
Then $F$ is a map of $G$-$\infty$-operads if and only if it sends an inert arrow in $E^{\otimes}$ over $\mathcal{F}$ to an inert arrow in $E'^{\otimes}$.
\end{lemma}
\begin{proof}
For a finite $G$-set $I=[U\rightarrow O]$ note that the maps $\chi_{[W\subseteq U]}$ all belong to $\mathcal{F}$. The proof is now analogous to \cite[2.1.2.9]{HA}.
\end{proof}

\begin{lemma}
\label{weakgapprox}
Let $p:E^{\otimes}\rightarrow\FinG$ be a $G$-$\infty$-operad and let $f:C\rightarrow E^{\otimes}$ be a $G$-approximation. Let $c\in C$ and let $\alpha: x\rightarrow f(c)$ be any morphism in $E^{\otimes}$. Consider
\[
\Sigma\subseteq C_{/c} \times_{E^{\otimes}_{/f(c)}} {E^{\otimes}_{x/}}_{/f(c)}
\]
the full subcategory spanned by the objects corresponding to pairs $\{\beta:d\rightarrow c, \gamma: x\rightarrow f(d)\}$ such that $\gamma$ is inert. The $\infty$-category $\Sigma$ is contractible.
\end{lemma}
\begin{proof}
We can factorize $\alpha$ as in the following commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
 & y \arrow[rd,"\alpha_2"] & \\
x \arrow[ur,"\alpha_1"]\arrow[rr,"\alpha"] & & f(c)
\end{tikzcd}
\end{center}
such that $\alpha_1$ is inert and $\alpha_2$ is active. By definition of a $G$-approximation, we have a Cartesian lift $\bar{\alpha}_2: \bar{y}\rightarrow c$ of $\alpha_2$ in $C$. Now, analogous to the proof of \cite[2.3.3.10]{HA} we can claim that the pair $\sigma = (\bar{\alpha}_2: \bar{y}\rightarrow c,\alpha_1 : x\rightarrow y = f(\bar{y}))$ is a terminal object of $\Sigma$, hence $\Sigma$ is contractible.
\end{proof}

\begin{remark}
In Lurie's book \cite{HA}, one can find a definition of a \emph{weak approximation} to be a map $C\rightarrow E^{\otimes}$ satisfying the second point from the definition \ref{defgapprox} and the condition from \ref{weakgapprox} (in the non-equivariant case). In this paper, we will stick to the work with (strong) $G$-approximation although one could add the definition of the weak one.
\end{remark}

\begin{proposition}
\label{ha23323}
Let $p:E^{\otimes}\rightarrow\FinG$ and $q:E'^{\otimes}\rightarrow\FinG$ be two $G$-$\infty$-operads and let $f:C\rightarrow E^{\otimes}$ be a $G$-approximation. Assume that the induced map $C_{I(-)}\rightarrow E$ is an equivalence of $G$-$\infty$-categories. Then the induced map
\[
\theta: \Alg_G(E,E') \rightarrow \Alg_G(C,E')
\]
is an equivalence of $\infty$-categories.
\end{proposition}
\begin{proof}
First, we can choose a Cartesian fibration $u:M\rightarrow \Delta^1$ associated to the functor $f$, together with isomorphisms $M\times_{\Delta^1} \{0\}\simeq E^{\otimes}$, $M\times_{\Delta^1} \{1\}\simeq C$ and a retraction $r:M\rightarrow E^{\otimes}$ such that $r|_{C} = f$. Denote with $\Upsilon \subseteq \Fun_{\FinG} (M,E')$ the full subcategory spanned by the functors $F:M\rightarrow E'$ over $\FinG$ such that:
\begin{enumerate}
\item The restriction $F|_{E^{\otimes}}$ belongs to $\Alg_G(E,E')$,
\item For every $u$-Cartesian morphism $\alpha$ of $M$, the image $F(\alpha)$ is an equivalence in $E'$ (or, equivalently, $F$ is a $q$-left Kan extension of $F|_{E^{\otimes}}$).
\end{enumerate}
We will continue the proof and complete it in several steps.
\begin{step}
The restriction map $\Upsilon\rightarrow \Alg_G(E,E')$ is a trivial Kan fibration.
\end{step}
Let $\mathcal{X}\subseteq \Fun_{\FinG}(M,E'^{\otimes})$ be the full subcategory spanned by those functors $F:M\rightarrow E'^{\otimes}$ which are $q$-left Kan extensions of $F|_{E^{\otimes}}$, and let $\mathcal{Y}\subseteq \Fun_{\FinG} (E^{\otimes},E'^{\otimes})$ be the full subcategory spanned by those functors $F:E^{\otimes}\rightarrow E'^{\otimes}$ such that for every $x\in M$ the induced functor $E^{\otimes}_{/x}\rightarrow E'^{\otimes}$ has a $q$-colimit, where $E^{\otimes}_{/x} := E^{\otimes}\times_M M_{/x}$. By \cite[4.3.2.15]{HTT} the restriction functor $\mathcal{X}\rightarrow\mathcal{Y}$ is a trivial Kan fibration. Moreover, we claim that $\mathcal{Y}\simeq \Fun_{\FinG} (E^{\otimes},E'^{\otimes})$. This follows from the fact that $E^{\otimes}_{/x}$ has a terminal object, hence every functor in $\Fun_{\FinG} (E^{\otimes},E'^{\otimes})$ has a $q$-colimit. The terminal object in $E^{\otimes}_{/x}$ is given by $x\rightarrow x$ if $x\in M|_{\{0\}}\simeq E^{\otimes}$ and by a Cartesian lift $y\rightarrow x$ over $x$ if $x\in M|_{\{1\}}\simeq C$. By the description of the $\infty$-category $\Upsilon$ the restriction functor $\Upsilon\rightarrow \Alg_G(E,E')$ fits in the commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
\Upsilon \arrow[d]\arrow[r,hookrightarrow] & \mathcal{X} \arrow[d]\arrow[r] & \Fun_{\FinG}(M,E') \arrow[d] \\
\Alg_G(E,E') \arrow[r,hookrightarrow] & \mathcal{Y} \arrow[r,"\simeq"] & \Fun_{\FinG} (E,E')
\end{tikzcd}
\end{center}
In fact, the left square is a pullback square, again by the description of $\Upsilon$, hence $\Upsilon\rightarrow \Alg_G(E,E')$ is a trivial Kan fibration.

Going toward our next step, note that precomposition with $r$ gives a section of this trivial fibration, which we will traditionally mark with $s$. Let $\epsilon: \Upsilon\rightarrow \Fun_{\FinG}(C,E'^{\otimes})$ be the other restriction. The functor $\theta$ is given by the composition $\epsilon\circ s$, which means that it will suffice to prove that $\epsilon$ induces an equivalence of $\infty$-categories $\Upsilon$ and $\Alg_G(C,E'^{\otimes})$.

Again, by \cite[4.3.2.15]{HTT} it will suffice to show the following:
\begin{enumerate}
\item for every $F_0\in \Alg_G(C,E')$ there exists $F\in \Fun_{\FinG}(M,E'^{\otimes})$ such that $F$ is a $q$-right Kan extension of $F_0$;
\item a functor $F\in \Fun_{\FinG}(M,E'^{\otimes})$ belongs to $\Upsilon$ if and only if it is a $q$-right Kan extension of $F_0 = F|_C$, with $F_0\in \Alg_G(C,E')$.
\end{enumerate}
Naturally, our next step would be to prove:
\begin{step}
\label{step2}
For every $F_0\in \Alg_G(C,E')$ there exists $F\in \Fun_{\FinG}(M,E'^{\otimes})$ such that $F$ is a $q$-right Kan extension of $F_0$.
\end{step}
Take $x\in E^{\otimes}$, let $C_{x/} = M_{x/}\times_M C$ and let $F_x = F_0 |_{C_{x/}}$. By \cite[4.3.2.13]{HTT} it will suffice to show that $F_x$ can be extended to a $q$-limit diagram $C_{x/}^{\lhd}\rightarrow E'^{\otimes}$ (covering the map $C_{x/}^{\lhd}\rightarrow M\rightarrow \FinG$). Denote with $C'_{x/}$ the full subcategory of $C_{x/}$ spanned by those morphisms $x\rightarrow y$ in $M$ such that $x\rightarrow f(y)$ is an inert arrow in $E^{\otimes}$. By \ref{weakgapprox} the inclusion functor $C'_{x/}\hookrightarrow C_{x/}$ is final, thus by \cite[4.3.1.7]{HTT} it will suffice to show that $F'_{x} = F_{x}|_{C'_{x/}}$ can be extended to a $q$-limit ${C'}_{x/}^{\lhd}\rightarrow E'^{\otimes}$.

Let $p(x) = [U\rightarrow O]$ and let $C''_{x/}$ be the full subcategory of $C'_{x/}$ spanned by inert morphisms $x\rightarrow f(y)$ such that their underlying map in $\FinG$ can be written as a span
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U \arrow[d] & V \arrow[d,"="]\arrow[r,"="]\arrow[l] & V\arrow[d,"="] \\
O & V\arrow[r,"="]\arrow[l] & V
\end{tikzcd}
\end{center}
where $V\in\OG$. At the moment, we wish to prove that $F'_x$ is a $q$-right Kan extension of $F''_x = F'_x |_{C''_{x/}}$ so that we can use \cite[4.3.2.7]{HTT}. Let $\alpha : x\rightarrow y$ be a map in $M$ which is an object of $C'_{x/}$ and denote $p\circ f(y) = [U_1\rightarrow O_1]$. The $\infty$-category $C''_{x/} \times_{C'_{x/}} (C'_{x/})_{\alpha /}$ can be identified with the full subcategory of $M_{\alpha /}$ spanned by diagrams $x\xrightarrow{\alpha} y \xrightarrow{\beta} z$ such that $p\circ f(\beta)$ can be written as the span
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U_1 \arrow[d] & V \arrow[d,"="]\arrow[r,"="]\arrow[l] & V\arrow[d,"="] \\
O_1 & V\arrow[r,"="]\arrow[l] & V
\end{tikzcd}
\end{center}
with $V\in\OG$. Note that the upper left $G$-map $V\rightarrow U_1$ factors through some $W\in \Orbit(U_1)$. Let, $\mathcal{F}_{W\subseteq U_1}$ be the full subcategory of ${\FinG}_{\chi_{[W\subseteq U_1]}/}$ spanned by those object (or better said, morpshisms) of the form
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U_1 \arrow[d] & V \arrow[d,"="]\arrow[r,"="]\arrow[l] & V\arrow[d,"="] \\
O_1 & V\arrow[r,"="]\arrow[l] & V
\end{tikzcd}
\end{center}
with $V\in\OG$. To be more precise, one such morphism can be factored as composition of maps 
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U_1 \arrow[d] & W \arrow[d,"="]\arrow[r,"="]\arrow[l] & W\arrow[d,"="] & V \arrow[d,"="]\arrow[l]\arrow[r,"="] & V \arrow[d,"="] \\
O_1 & W\arrow[r,"="]\arrow[l] & W & V \arrow[l]\arrow[r,"="] & V
\end{tikzcd}
\end{center}
Now we can write our $\infty$-category $C''_{x/} \times_{C'_{x/}} (C'_{x/})_{\alpha /}$ as the disjoint union of $\infty$-categories $C''(W)_{y/}$, for $W\in \Orbit(U_1)$, where each $C''(W)_{y/}$ is equivalent to the full subcategory of $C_{y/}$ spanned by objects (that is, morphisms) covering a map from $\mathcal{F}_{W\subseteq U_1}$. Since $f$ is a $G$-approximation all of these $\infty$-categories $C''(W)_{y/}$ have an initial object given by the $p\circ f$-coCartesian lift $y\rightarrow y_W$ covering $\chi_{[W\subseteq U_1]}$. Hence, it will suffice to show that $F_0(y)$ is a $q$-product of the objects $\{F_0(y_W)\}_{W\in \Orbit(U_1)}$. Since $E'^{\otimes}$ is a $G$-$\infty$-operad it will suffice to show that the maps $F_0(y)\rightarrow F_0(y_W)$ are inert, which is true since $F_0\in \Alg_G(C,E)$.

We have shown that $F'_x$ is a $q$-right Kan extension of $F''_x = F'_x |_{C''_{x/}}$. By \cite[4.3.2.7]{HTT} it will suffice to prove that $F''_{x}$ can be extended to a $q$-limit diagram ${C''}_{x/}^{\lhd}\rightarrow E'^{\otimes}$ covering the map ${C''}_{x/}^{\lhd}\rightarrow M\rightarrow \FinG$. Similarly as before, let $C''(W)_{x/}$ (for $W\in \Orbit(U)$ with $p(x) = [U\rightarrow O]$) be the full subcategory of $C''_{x/}$ spanned by objects covering a map from $\mathcal{F}_{W\subseteq U}$. Now the $\infty$-category $C''_{x/}$ can be written as the disjoint union of $\infty$-categories $C''(W)_{x/}$. Denote with
\[
E(W) \subseteq E^{\otimes}_{x/} \times_{{\FinG}_{[U\rightarrow O]/}} \mathcal{F}_{W\subseteq U}
\]
the full subcategory such that we have an equivalence $C''(W)_{x/}\simeq E(W) \times_{E} C_{I(-)}$. Since $f$ induces an equivalence on the underlying $G$-$\infty$-categories $C_{I(-)}\simeq E$ this is possible to do. Furthermore, we can choose inert morphisms $x\rightarrow x_W$ as coCartesian lifts of $\chi_{[W\subseteq U]}$ which in turn represent the initial objects of $E(W)$ for every $W\in \Orbit(U)$. Since $f$ induces a categorical equivalence $C_{I(-)}\xrightarrow{\simeq} E$ we can write $x_W \simeq f(c_W)$ with $\alpha_W : x\rightarrow c_W$ an initial object of $C''(W)_{x/}$. Similarly to the previous part, we are required to prove the existence of a $q$-product of objects $F_0(c_W)$, with $W\in \Orbit(U)$, which follows from the fact that $E'^{\otimes}$ is a $G$-$\infty$-operad. This finishes the proof of the second step.

The arguments above give us the following equivalent condition for Step \ref{step2}:
\theoremstyle{thmstyleone}
\newtheorem*{hlemma}{Help lemma}
\begin{hlemma}
Let $F\in \Fun_{\FinG}(M,E'^{\otimes})$ be a functor such that $F_0 = F|_{C} \in \Alg_G (C,E')$. Let $x\in E^{\otimes}$ be an element such that $p(x) = [U\rightarrow O]$, and let $c_W\in C$ be the elements such that $f\circ p(c_W) = [W\xrightarrow{=}W]$ for every $W\in \Orbit(U)$. Additionally, let $\alpha_W : x\rightarrow c_W$ be maps in $M$ covering $\chi_{[W\subseteq U]}$ constructed as above. Then $F$ is a $q$-right Kan extension of $F_0$ if and only if $F(\alpha_W)$ are inert arrows in $E'^{\otimes}$ for every $W\in \Orbit(U)$.
\end{hlemma}
This help lemma will turn fundamental in the proof of our third and final step:
\begin{step}
A functor $F\in \Fun_{\FinG}(M,E'^{\otimes})$ belongs to $\Upsilon$ if and only if it is a $q$-right Kan extension of $F_0 = F|_C$, with $F_0\in \Alg_G(C,E')$.
\end{step}
Let $F\in\Upsilon$. The functor $F_0 = F|_C$ is equivalent to the functor $F|_{E^{\otimes}} \circ f$ hence $F_0 \in \Alg_G (C,E')$.  Our help lemma now implies that $F$ is a $q$-right Kan extension of $F_0$.

For the other direction, let $F\in \Fun_{\FinG}(M,E'^{\otimes})$ and let $F_0 = F|_{C}\in \Alg_G(C,E')$. Assume that $F$ is a $q$-right Kan extension of $F_0$. Let $c\in C$ with $f\circ p(c) = [U\rightarrow O]$. Furthermore, let $x=f(c)$. We would like to show that $F(x)\rightarrow F(c)$ in an equivalence in $E'^{\otimes}$. For that, let us choose $p'$-coCartesian (with $p' = f\circ p$) lifts $c\rightarrow c_W$ over $\chi_{[W\subseteq U]}$. Since $F_0 \in \Alg_G (C,E')$ by assumption, the maps $F_0(c)\rightarrow F_0(c_W)$ are all inert. Since $E'^{\otimes}$ is a $G$-$\infty$-operad, it will suffice to show that $F(x)\rightarrow F(c_W)$ are all inert, which is true by the help lemma above.

What is left to show is that $F|_{E}\in \Alg_G(E,E')$. By \ref{gopinert} it would only suffice to check that the inert map $x\rightarrow x_V$ lying over
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U \arrow[d] & V \arrow[d,"="]\arrow[r,"="]\arrow[l] & V\arrow[d,"="] \\
O & V\arrow[r,"="]\arrow[l] & V
\end{tikzcd}
\end{center}
maps to an inert map, with $V\in\OG$. This map factors as $x\rightarrow x_W\rightarrow x_V$ lying over 
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U \arrow[d] & W \arrow[d,"="]\arrow[r,"="]\arrow[l] & W\arrow[d,"="] & V \arrow[d,"="]\arrow[l]\arrow[r,"="] & V \arrow[d,"="] \\
O & W\arrow[r,"="]\arrow[l] & W & V \arrow[l]\arrow[r,"="] & V
\end{tikzcd}
\end{center}
with $x\rightarrow x_W$ being inert and $W\in \Orbit(U)$. By the dual of \cite[2.4.1.7]{HTT} the map $x_W\rightarrow x_V$ is also inert. It is enough to show that $F(x)\rightarrow F(x_W)$ and $F(x_W)\rightarrow F(x_V)$ are inert.

Similarly as before, we can assume that $x_W = f(c_W)$ and $x_V = f(c_V)$, for some $c_W,c_V\in C$. Since the maps $F(x_W)\rightarrow F(c_W)$ and $F(x_V)\rightarrow F(c_V)$ are equivalences in $E'^{\otimes}$, for the map $F(x)\rightarrow F(x_W)$ to be inert it would suffice to show that the composite map $F(x)\rightarrow F(x_W)\rightarrow F(c_W)$ is inert, which follows from our \emph{help lemma}. As for $F(x_W)\rightarrow F(x_V)$, note that it is equivalent to $F(c_W)\rightarrow F(c_V)$ which is further equivalent to $F_0(c_W)\rightarrow F_0(c_V)$. Finally, since $F_0 \in \Alg_G (C,E')$ this map is inert and so is $F(x_W)\rightarrow F(x_V)$. With this the proof is finished.
\end{proof}
As an immediate consequence we have the following:
\begin{corollary}
Let $f:E^{\otimes}\rightarrow E'^{\otimes}$ be a map of $G$-$\infty$-operads. Furthermore, assume $f$ is a $G$-approximation map that induces an equivalence on the underlying $G$-$\infty$-categories. Then $f$ is an equivalence of $G$-$\infty$-operads.
\end{corollary}

\subsection{The universal property}

In this section we will prove the universal property of $G$-disc algebras. Let $H\leq G$ be a finite subgroup of a compact Lie group $G$. The statement that we want to prove is the following: the $G$-symmetric monoidal category of $G/H$-framed $G$-discs is freely generated by the $H$-symmetric monoidal category of $V$-framed $H$-discs, where $V$ is an $H$-representation. In other words, for a $G$-symmetric monoidal $\infty$-category $\Cs$ we have the following equivalence:
\[
\Fun^{\otimes}_G (\underline{\Disk}^{G,G/H\fr},\Cs) \simeq \Fun^{\otimes}_H (\underline{\Disk}^{H,V\fr},\underline{G/H}\underline{\times} \Cs)
\]
where $\underline{G/H}\underline{\times} \Cs$ is the underlying $H$-$\infty$-category of $\Cs$.

Note that by \ref{genv} $\underline{\Disk}^{G,G/H\fr}$ and $\underline{\Disk}^{H,V\fr}$ are equivalent to the $G$-symmetric monoidal envelopes $\Env_G (\RGHs)$ and $\Env_H (\RHVs)$ respectively. For simplicity, let us denote with $\DGH := \RGHs$ and $\DHV := \RHVs$. Now the equivalence above can be written as
\begin{equation}
\label{universalpg}
\Alg_G (\DGH, \Cic) \simeq \Alg_H (\DHV, \underline{G/H}\underline{\times} \Cic)
\end{equation}

\begin{mydescription}
\label{lp10rmk21}
Before continuing, let us give more insight into the objects of $\RHVs$ and $\RGHs$. Since the objects of $(\RHVs)_{I(-)}$ are framed over a point, they correspond to the $V$-framed $G$-discs. Informally, using \ref{framingongdiscs} we can depict these objects as
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
H/K \times V \arrow[d]\arrow[r] & V \arrow[d] \\
H/K \arrow[r]\arrow[d,"="] & \ast \\
H/K &
\end{tikzcd}
\end{center}
where the lower horizontal arrow is the framing map and the square is a pullback square.

Generally speaking, the underlying $H$-$\infty$-category $\Cic_H$ of a $G$-$\infty$-category $\Cic$ is equivalent to $\underline{G/H}\underline{\times}\Ci$ where $\underline{G/H} = (\OG^{\op})_{(G/H)/}$, hence, a $K$-object in $\Cic_H$ i.e. an object over an orbit $H/K$ corresponds to an object over $G/K\rightarrow G/H$ in $\Cic$. Additionally, composing with the map $G/K\rightarrow G/H$ represents topological induction. Therefore, the $H$-disc above corresponds to the element
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
E \arrow[d]\arrow[r] & G\times_H V \arrow[d] \\
G/K \arrow[r]\arrow[d,"="] & G/H \\
G/K \arrow[d] & \\
G/H &
\end{tikzcd}
\end{center}
such that the square in the diagram is a pullback square. Such element is a $G/H$-framed $G$-disc, with the framing map $G/H\rightarrow\BOG$ being adjoint to the framing map on $H$-discs $\ast\rightarrow \operatorname{BO}_n(H)$. Moreover, note that the framing map is the same as the map inducing topological induction, that is the composition of the lower two vertical arrows. Therefore we can write this element as $E \rightarrow G/K \xrightarrow{=} G/K \rightarrow G/H$ or even simpler as $G/K \xrightarrow{=} G/K \rightarrow G/H$ (since all the information on the bundle over $G/K$ is carried by the framing map). With this depiction the general object of $\RHVs$ can be written as
\[
U \rightarrow O \rightarrow G/H
\]
where $U$ is a finite $G$-set and $O\in\OG$ is an orbit, with the composition $U\rightarrow G/H$ representing the framing map as well.

Similarly, an object of $(\RGHs)_{I(-)}$ can be written in the form
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
E \arrow[d]\arrow[r] & G\times_H V \arrow[d] \\
G/K \arrow[r]\arrow[d,"="] & G/H \\
G/K  & 
\end{tikzcd}
\end{center}
where the lower horizontal map is the framing map and the square is a pullback square. Again, by \ref{framingongdiscs} we can write this element as
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
G/K \arrow[r]\arrow[d,"="] & G/H \\
G/K & 
\end{tikzcd}
\end{center}
with the horizontal map being the framing map. Therefore, the elements of $\RGHs$ can be written in the form
\[
O \leftarrow U \rightarrow G/H
\]
where $U$ is a finite $G$-set and $O\in\OG$ is an orbit, the left arrow is the structure map while the right arrow is the framing map.
\end{mydescription}

In order to prove the equivalence \eqref{universalpg} we would like to be able to use \ref{ha23323}.
\begin{construction}
Let us construct a map $\theta : \DHV\rightarrow\DGH$ as part of the commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
\DHV \arrow[r,"\theta"]\arrow[d] & \DGH \arrow[d] \\
\FinH \arrow[r] & \FinG
\end{tikzcd}
\end{center}
Note that $\FinH$ is equivalent to $\underline{G/H}\underline{\times}\FinG$. Therefore the map $\FinH\rightarrow\FinG$ is a left fibration.

By \ref{lp10rmk21} we have a description of the objects of $\DHV$ and $\DGH$. The object $(U\rightarrow O\rightarrow G/H)\in\DHV$ is then sent by the map $\theta$ to the object $(O\leftarrow U\rightarrow O\rightarrow G/H)\in\DGH$.
\end{construction}

\begin{proposition}
\label{lp10thm23}
The map $\theta:\DHV\rightarrow\DGH$ is a $G$-approximation map. Moreover, $\theta$ induces an equivalence on the underlying $G$-$\infty$-categories.
\end{proposition}
\begin{proof}
In order to prove that $\theta$ is a $G$-approximation map we need to prove the three points from \ref{defgapprox}:
\begin{enumerate}
\item Consider the following commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
\DHV \arrow[rrr,"\theta"]\arrow[dd] & & & \DGH \arrow[dd] &  \\
 & \RHV \arrow[ul]\arrow[dd] & & & \RGH \arrow[ul]\arrow[dd] \\
\FinH \arrow[rrr] & & & \FinG & \\
& \OH^{\op} \arrow[ul,"I(-)"]\arrow[rrr] & & & \OG^{\op} \arrow[ul,"I(-)"]
\end{tikzcd}
\end{center}
where the right rhombus is a pullback diagram. If we restrict our attention to the part of the diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
\underline{\Rep}_n^{V\fr}(H) \arrow[r]\arrow[d] & \DHV \arrow[d]\simeq \RHVs \\
\OH^{\op} \arrow[r,"I(-)"]\arrow[d] & \FinH \arrow[d] \\
\OG^{\op} \arrow[r,"I(-)"] & \FinG
\end{tikzcd}
\end{center}
we have that the upper square is a pullback square by definition. Additionally, by inspection, the lower square is a pullback square, meaning that the outer rectangle is a pullback diagram. Therefore, the pullback of $\DHV\rightarrow\FinH\rightarrow\FinG$ along $I(-):\OG^{\op}\rightarrow\FinG$ is $\RHV\rightarrow \OH^{\op} \rightarrow \OG^{\op}$. Additionally, the first map in the composition is a coCartesian fibration since $\RHV$ is an $H$-$\infty$-category and $\OH^{\op}\simeq\underline{G/H}\rightarrow \OG^{\op}$ is a left fibration, meaning that the composition is a coCartesian fibration i.e. $\RHV\rightarrow \OG^{\op}$ is a $G$-$\infty$-category. Additionally, since the right rhombus is a pullback diagram, $\theta$ induces a map that fits into the following commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
\underline{\Rep}_n^{V\fr}(H) \arrow[r]\arrow[d] & \underline{\Rep}_n^{G/H\fr}(G) \arrow[d] \\
\underline{G/H}\simeq\OH^{\op} \arrow[r] & \OG^{\op}
\end{tikzcd}
\end{center}
\item Let $x\in\DHV$ be such that $\theta(x)$ lies over $I : U\rightarrow O \in \FinG$. Note that $I$ lies in an image of $\FinH\rightarrow\FinG$ i.e. $I$ is an image of an element $I': U'\rightarrow O'$ of $\FinH$. Since $\FinH\rightarrow\FinG$ is a left fibration (and, in particular, a coCartesian fibration), the maps $\chi_{[W\subseteq U]}$ in $\FinG$ have coCartesian lifts in $\FinH$ which are exactly maps $\chi_{[W'\subseteq U']}$. Now, considering that $\DHV\rightarrow\FinH$ is an $H$-$\infty$-operad, the coCartesian lifts of $\chi_{[W'\subseteq U']}$ exist with the source $x$. By the commutativity of the upper diagram, these lifts represent the desired coCartesian lifts $x\rightarrow x_W$ of $\chi_{[W\subseteq U]}$ in $\DHV$. It is clear that the maps $\theta(x\rightarrow x_W)$ are inert in $\DGH$.
\item Recall that, by \ref{lp10rmk21}, objects of $\DGH$ can be depicted as
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U \arrow[r]\arrow[d] & G/H \\
O &
\end{tikzcd}
\end{center}
with $U\in\FinG$ and $O\in\OG$ where the horizontal map corresponds to the framing map. Now let $x\in \DGH$ lying over $U_1\rightarrow O$, $c\in \DHV$ lying over $U_2\rightarrow O$ and let $x\rightarrow\theta(c)$ be an active arrow lying over diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
U_1 \arrow[r]\arrow[d]\arrow[rr, bend left] & U_2 \arrow[d] & G/H \arrow[d,"="] \\
O \arrow[r,"="] & O \arrow[r] & G/H
\end{tikzcd}
\end{center}
Note that a map in $\DGH$ should be represented by a span, but since the underlying arrow is fiberwise active, the left side of the span would be the identity, hence we omit it in the diagram. The element $\bar{x}$ of the Cartesian lift corresponds to the element $U_1 \rightarrow O \xrightarrow{=} O \rightarrow G/H$.
\end{enumerate}

What is left to show is that $\theta$ induces equivalence on the underlying $G$-$\infty$-categories. Let us denote with $\theta_{I(-)}:\DHV_{I(-)}\rightarrow \DGH_{I(-)}$ the induced functor. Note that the element of $\DGH_{I(-)}$ can be written as
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
O \arrow[r]\arrow[d,"="] & G/H \\
O &
\end{tikzcd}
\end{center}
which is the same as $O\xrightarrow{=} O\rightarrow G/H$, an element of $\DHV_{I(-)}$, hence $\theta_{I(-)}$ is essentially surjective. As for the mapping spaces, recall that the mapping space in $\DHV_{I(-)}$ between $E_1 \rightarrow O_1 \xrightarrow{=} O_1 \rightarrow G/H$ and $E_2 \rightarrow O_2 \xrightarrow{=} O_2 \rightarrow G/H$ consists of the spans
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
E_1 \arrow[d] & E \arrow[d]\arrow[l]\arrow[r] & E_2 \arrow[d] \\
O_1 \arrow[d,"="] & O_2 \arrow[l]\arrow[r,"="]\arrow[d,"="] & O_2 \arrow[d,"="] \\
O_1 \arrow[dr] & O_2 \arrow[l]\arrow[r,"="]\arrow[d] & O_2 \arrow[dl] \\
 & G/H &
\end{tikzcd}
\end{center}
which is the same as the span
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
E_1 \arrow[d] & E \arrow[d]\arrow[l]\arrow[r] & E_2 \arrow[d] & \\
O_1 \arrow[d,"="]\arrow[drrr] & O_2 \arrow[l]\arrow[r,"="]\arrow[d,"="]\arrow[drr] & O_2 \arrow[d,"="]\arrow[dr] & \\
O_1 & O_2 \arrow[l]\arrow[r,"="] & O_2 & G/H \\
\end{tikzcd}
\end{center}
representing the map of the image of $\theta_{I(-)}$. We conclude that $\theta_{I(-)}$ is fully faithful and hence an equivalence which finishes the proof.
\end{proof}

Propositions \ref{lp10thm23} and \ref{ha23323} give us the following result:

\begin{corollary}
\label{lp10cor24}
Let $E^{\otimes}$ be a $G$-$\infty$-operad. The map $\theta$ induces an equivalence
\[
\Alg_G(\DGH,E) \xrightarrow{\simeq} \Alg_G (\DHV,E)
\]
\end{corollary}
We are one step away from proving our universal property:
\begin{theorem}
\label{universalthm}
Let $\Cs$ be a $G$-symmetric monoidal category. Then the $G$-symmetric monoidal category of $G/H$-framed $G$-discs is freely generated by the $H$-symmetric monoidal category of $V$-framed $H$-discs. In other words, there is an equivalence
\begin{equation*}
\Fun^{\otimes}_G (\underline{\Disk}^{G,G/H\fr},\Cs) \xrightarrow{\simeq} \Fun^{\otimes}_H (\underline{\Disk}^{H,V\fr},\Cs_H)
\end{equation*}
where $\Cs_H$ is the underlying $H$-symmetric monoidal category of $G$-symmetric monoidal category $\Cs$, and where $V$ is a $G$-representation.
\end{theorem}
\begin{proof}
As discussed in the beginning of this section, the above statement is equivalent to
\[
\Alg_G(\DGH,\Cic) \xrightarrow{\simeq} \Alg_H(\DHV,\Cic_H)
\]
By \ref{lp10cor24} it will suffice to find an equivalence
\[
\Alg_G (\DHV,\Cic) \xrightarrow{\simeq} \Alg_H(\DHV,\Cic_H)
\]
Recall that the $H$-symmetric monoidal category $\Cs_H$ is obtained via the commutative diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
\Cs_H \arrow[d]\arrow[r] & \Cs \arrow[d] \\
\FinH \arrow[d]\arrow[r] & \FinG \arrow[d] \\
\underline{G/H} \arrow[r] & \OG^{\op}
\end{tikzcd}
\end{center}
where both inner rectangles (and consequently also the outer rectangle) are pullbacks.

Let $F$ be a $\DHV$-algebra object in $\Cs$ i.e. $F\in \Alg_G(\DHV,\Cic)$, and consider the following diagram
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=2em]
 & \Cs_H \arrow[dr]\arrow[dd] & \\
\DHV \arrow[rr,"F" near start]\arrow[ur,dashed,"F' "]\arrow[dr]\arrow[dd] & & \Cs \arrow[dd] \\
 & \FinH \arrow[dr] & \\
\DGH \arrow[rr] & & \FinG
\end{tikzcd}
\end{center}
By the universal property of the pullback, $F$ induces a functor $F' :\DHV\rightarrow\Cs_H$. We would like to show that $F' \in \Alg_H(\DHV,\Cs_H)$.

Let $\alpha_W$ be an inert map in $\DHV$ covering the map $\chi_{[W\subseteq U]}: [U\rightarrow O] \rightarrow [W\xrightarrow{=}W]$ in $\FinH$. Since $\FinH\rightarrow\FinG$ is a left fibration and $F\in \Alg_G(\DHV,\Cs)$, $F(\alpha_W)$ is inert in $\Cs$. Again, since $\FinH\rightarrow\FinG$ is a left fibration, and consequently $\Cs_H\rightarrow\Cs$, the pullback of $F(\alpha_W)$ is inert in $\Cs_H$, which is exactly $F'(\alpha_W)$, meaning $F'\in \Alg_H(\DHV,\Cs_H)$. Similarly, if we would have taken $F'\in \Alg_H(\DHV,\Cs_H)$ the induced functor $F:\DHV\rightarrow\Cs_H \rightarrow\Cs$ would lie in $\Alg_G(\DHV,\Cs)$. By the universality of the maps to the pullback we have 
\[
\Alg_G (\DHV,\Cic) \xrightarrow{\simeq} \Alg_H(\DHV,\Cic_H)
\]
and the proof is finished.
\end{proof}


\subsection{Applications of the universal property}
\label{applications}

In this section, we will give two applications of the universal property of $G$-discs: algebras with genuine involution and $O(2)$-genuine objects, and associative algebras and $S^1$-genuine objects.

\addtocontents{toc}{\protect\setcounter{tocdepth}{1}}

\subsection*{Algebras with genuine involution and $O(2)$-genuine objects}

Let $G = O(2)$ and regard $H=\Ztwo$ as a subgroup generated by a reflection. To add on, let $\underline{\Sp}^{O(2)}$ be the $O(2)$-$\infty$-category of $O(2)$-spectra. Let $V$ be the adjoint representation of $O(2)$. It is evident that $V$ is endowed with $O(2)$-action, which, when restricted to $\Ztwo$-action becomes $\mathbb{R}^{\sigma}$ where $\sigma$ is an one dimensional sign representation.

Let $A_H$ be the $\mathbb{R}^{\sigma}$-framed $\Ztwo$-disc algebra object in $\underline{\Sp}^{\Ztwo}$. Let us give more insight into the structure of $A_H$. The objects of $\underline{\Disk}^{\Ztwo,\mathbb{R}^{\sigma}\fr}$ are given by the finite disjoint unions of
\begin{itemize}
\item $\mathbb{R}^{\sigma}$, which corresponds to the element $\mathbb{R}^{\sigma}\rightarrow \Ztwo /\Ztwo$;
\item the restriction $\Res^{\Ztwo}_{\{e\}}(\mathbb{R}^{\sigma}) = \mathbb{R}^1$, which corresponds to the element $\sqcup_{\Ztwo} \mathbb{R}^1 \rightarrow \Ztwo/\{e\}$;
\item the topological induction $\sqcup_{\Ztwo} \mathbb{R}^1$ obtained as the element $\sqcup_{\Ztwo} \mathbb{R}^1 \rightarrow \Ztwo/\{e\}\rightarrow \Ztwo / \Ztwo$.
\end{itemize}
Therefore, we can write
\begin{itemize}
\item $\Res^{\Ztwo}_{\{e\}} A_H (\mathbb{R}^{\sigma}) = A_H(\mathbb{R}^1)$;
\item $A(\sqcup_{\Ztwo} \mathbb{R}^1) \simeq N^{\Ztwo}_{e} (A_H (\mathbb{R}^{1}))$.
\end{itemize}
Additionally, the equivariant embedding
\[
(\sqcup_{\Ztwo} \mathbb{R}^1)\sqcup \mathbb{R}^{\sigma} \hookrightarrow \mathbb{R}^{\sigma}
\]
induces a map $N^{\Ztwo}_{e} (A_H (\mathbb{R}^{1})) \otimes A(\mathbb{R}^{\sigma}) \rightarrow A(\mathbb{R}^{\sigma})$. Meaning that the $\Ztwo$-spectrum $A(\mathbb{R}^{\sigma})$ has a structure of a $N^{\Ztwo}_{e} (A_H (\mathbb{R}^{1}))$-module.

Next, note that $A_H(\mathbb{R}^1)$ has a structure of an $\mathbb{E}_1$-algebra object in $\underline{\Sp}^{\Ztwo}_{[\Ztwo/\{e\}]} \simeq \Sp$, since
\[
\Fun^{\otimes}(\underline{\Disk}^{\Ztwo,\mathbb{R}^{\sigma}\fr}_{[\Ztwo/\{e\}]} , \underline{\Sp}^{\Ztwo}_{[\Ztwo/\{e\}]}) \simeq \Fun^{\otimes}(\Disk^{1\fr},\Sp) \simeq \Alg_{\mathbb{E}_1}(\Sp)
\]
Moreover, the $\Ztwo$-action makes $A_H (\mathbb{R}^1)$ into an associative ($\mathbb{E}_1$) algebra with involution i.e. $A_H (\mathbb{R}^1)$ is a $A_H (\mathbb{R}^1)\otimes A_H (\mathbb{R}^1)$-module. To add on, we have seen that this $A_H (\mathbb{R}^1)\otimes A_H (\mathbb{R}^1)$-module structure lifts to $N^{\Ztwo}_{e} (A_H (\mathbb{R}^{1}))$-module structure on $A(\mathbb{R}^{\sigma})$, hence we say that $A_H$ is an associative algebra with genuine involution.

The universal property of  equivariant disc algebras, Theorem \ref{universalthm}, gives us the equivalence
\[
\Fun^{\otimes}_{\Ztwo} (\underline{\Disk}^{\Ztwo,\mathbb{R}^{\sigma}\fr}, \underline{\Sp}^{\Ztwo}) \simeq \Fun^{\otimes}_{O(2)}(\underline{\Disk}^{O(2),S^1\fr},\underline{\Sp}^{O(2)})
\]
where we have used the fact that $O(2)/\Ztwo \cong S^1$.

Let $A\in \Fun^{\otimes}_{O(2)}(\underline{\Disk}^{O(2),S^1\fr},\underline{\Sp}^{O(2)})$ be an $O(2)$-disc algebra corresponding to $A_H$. We can regard $S^1$ as a genuine $O(2)$-object (i.e. a coCartesian section) in the $O(2)$-$\infty$-category of manifolds $\underline{\Mfld}^{O(2),S^1\fr}$ given by
\begin{align*}
\underline{S^1} : & \mathcal{O}_{O(2)}^{\op} \rightarrow \underline{\Mfld}^{O(2),S^1\fr} \\
 O & \mapsto O\times S^1
\end{align*}
Therefore, we can build the following map
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
\{ \text{Associative algebras with genuine involution in } \underline{\Sp}^{\Ztwo}\} \arrow[d] \\
\{ \text{Genuine $O(2)$-objects in } \underline{\Sp}^{O(2)} \}
\end{tikzcd}
\end{center}
given by
\[
A_H \mapsto \int_{S^1} A
\]
The result of Horev, \cite[7.1.1 and 7.1.2]{AH19} tells us that the underlying $\Ztwo$-genuine object of $\int_{S^1} A$ is equivalent to the real topological Hochschild homology $\THR(A)$ (where we have written $A$ for $A_{[O(2)/C_2]}$) (see also \cite{DMPR17}). In other words, we have
\[
\left(\int_{S^1} A \right)_{[O(2)/\Ztwo]} \simeq \THR(A)
\]
Therefore, we have obtained the refinement of the $\Ztwo$-genuine structure on $\THR(A)$ to the $O(2)$-genuine structure.

\subsection*{Associative algebras and $S^1$-genuine objects}

For the second example, let us take $G=S^1$ and $H=\{e\}$ the trivial subgroup. The adjoint representation of $S^1$ is equal to $\mathbb{R}^1$ when forgetting the action, hence the $\infty$-category $\Fun^{\otimes}(\underline{\Disk}^{e,\mathbb{R}\fr}, \underline{\Sp}^{S^1}_{[S^1/e]})$ is equivalent to the $\infty$-category of $\mathbb{E}_1$-algebra objects in $ \underline{\Sp}^{S^1}_[S^1/e] \simeq \Sp$. Therefore, the theorem \ref{universalthm} gives us
\[
\Alg_{\mathbb{E}_1}(\Sp) \simeq \Fun^{\otimes}_{S^1}(\underline{\Disk}^{S^1,S^1\fr},\underline{\Sp}^{S^1})
\]
Let $A^{\operatorname{ass}}_e$ be an associative algebra object in the $\infty$-category of spectra $\Sp$ which corresponds to the $S^1$-framed $S^1$-algebra object $A$ in $\underline{\Sp}^{S^1}$. Then we can construct a map
\begin{center}
\begin{tikzcd} [row sep=2em, column sep=3em]
\{ \text{Associative algebras in } \Sp\} \arrow[d] \\
\{ \text{Genuine $S^1$-objects in } \underline{\Sp}^{S^1} \}
\end{tikzcd}
\end{center}
given by
\[
A_e^{\operatorname{ass}} \mapsto \int_{S^1} A
\]
Where the $S^1$-factorization homology is taken with respect to $S^1$ as an $S^1$-genuine object given by
\begin{align*}
\underline{S}^1 : & \mathcal{O}_{S^1}^{\op} \rightarrow \underline{\Mfld}^{S^1,S^1\fr} \\
 O & \mapsto O\times S^1
\end{align*}
By \cite[7.2.2]{AH19} we have
\[
\left( \int_{S^1} A \right)_{[S^1/C_n]}^{\Phi C_n} \simeq \THH(A;A^\tau)
\]
where $A^{\tau}$ is a $A$-$A^{\op}$-bimodule given by the formula
\begin{align*}
& A\otimes A^\tau \otimes A  \rightarrow A^\tau \\
& x \otimes a \otimes y  \rightarrow \tau x \otimes a \otimes y
\end{align*}
with $\tau\in C_n$ being the group generator.
