\ket{\eta_1} &=& \ket{+++}_{\gamma=1}, 
\nonumber \\
\ket{\eta_2} &=& \frac{1}{\sqrt{2}{\varepsilon}_0}\big(\ket{++-}-\ket{-++}\big)_{\gamma=1},
\nonumber \\
\ket{\eta_3} &=& \frac{1}{\sqrt{6}{\varepsilon}_0}\big(\ket{++-}+\ket{-++}-2\ket{+-+}\big)_{\gamma=1}.
\end{eqnarray}
