\section{Experimental realization in Floquet systems} 
%%
%%%%
\begin{figure}[t!]     
	\centering
	\includegraphics[width=0.98\linewidth]{fig4.pdf}
	\caption{(a) The periodic driving protocol to realize an effective three-body interaction. (b1) and (b2) show the real and imaginary components of the energy spectrum corresponding to the effective Hamiltonian  Eq.~(\ref{Heff}) around an EP$_4$ as functions of the perturbation strength $\epsilon$. In these plots, we set $TJ=0.2$. 
	}
	\label{fig4} %% label for entire figure
\end{figure}
%%%%
%%
Finally, we propose to realize a multi-body interaction by periodically driving a Hamiltonian with two-body interaction 
%
\begin{eqnarray}
\mathcal{H}(t) = J(t)\bar{\mathcal{H}}_1 + \epsilon(t)\bar{\mathcal{H}}_2 + \mathcal{H}_0,
\end{eqnarray}
%
where the two interaction terms are
%
\begin{eqnarray}
\bar{\mathcal{H}}_1 = \sum_{k\neq l}\sigma_{x}^k\sigma_{y}^l,\quad\bar{\mathcal{H}}_2 = \sum_{k\neq l}\sigma_{z}^k\sigma_{x}^l.
\end{eqnarray}
%
The parameters are assumed to vary in the form of step functions within a driving period $T$, as illustrated in Fig.~\ref{fig4}(a),
%
\begin{eqnarray}
J(t) &=& J\Big[\Theta(\frac{T}{4}-t) + \Theta(T-t)\Theta(t-\frac{3}{4}T) \notag\\
&&\quad- \Theta(t-\frac{T}{4})\Theta(\frac{3}{4}T-t)\Big],
\\
\epsilon(t) &=&\epsilon\,\Theta(t-\frac{T}{2}),
\end{eqnarray}
%
where $\Theta(x)$ is the Heaviside step function.
The corresponding time-evolution operator with the aid of Magnus expansion~\cite{Kennes-2020} at high frequency ($1/T\gg \epsilon, J, \gamma$) can be written as $\mathcal{U}(t) = {\rm exp}[{\Omega(t)}] = {\rm exp}[{\sum_{k=0}^{+\infty}\Omega_k(t)}]$, where 
%
\begin{eqnarray}
\Omega_1(t) &=& \int_0^tdt_1 A(t_1),
\nonumber \\
\Omega_2(t) &=& \frac{1}{2}\int_0^tdt_1\int_0^{t_1}dt_2[A(t_1),A(t_2)]
\end{eqnarray}
% 
with $A(t)=-i\mathcal{H}(t)$. At the time of complete periods, the evolution can be described by an effective Floquet Hamiltonian $\mathcal{H}_{\rm eff} = i(\Omega_1+\Omega_2+\cdots)/T$.
For a three-qubit system, the effective Hamiltonian up to the second-order expansion is given by 
%
\begin{eqnarray}
\mathcal{H}_{\rm eff}
= \Big(\mathcal{H}_0 + \frac{1}{2}\epsilon \bar{\mathcal{H}}_2\Big) +i\epsilon\frac{T}{8}\Big([\mathcal{H}_0,\bar{\mathcal{H}}_2]+\frac{1}{2}J[\bar{\mathcal{H}}_2,\bar{\mathcal{H}}_1]\Big).\notag\\
\label{Heff}
\end{eqnarray}
%
An effective three-body interaction thus emerges in the commutation operator $[\bar{\mathcal{H}}_2,\bar{\mathcal{H}}_1]$.
The effective Hamiltonian Eq.~(\ref{Heff}) contains both two- and three-body interactions, and presents fourth-order response to the interaction strength $\epsilon$ around the EP$_4$, as witnessed by the 1/4 slope in the inset of Figs.~\ref{fig4}(b). An effective interaction involving more particles can in principle be realized by going to higher orders of Magnus expansion.



