\appendix
\section{Expansions of propagators and vertices around flat space\label{appendix_expansions}}
\subsection{Propagator}
The propagator in curved space satisfies equation
\begin{equation}
e(x) \left[ie_a^\mu\gamma^a\left(\partial_\mu-\Omega_\mu\right)-m\right]S_g(x,y)=-\delta^{(4)}(x-y).
\end{equation}
One can transform the propagator as
\begin{align}
S_g=&-\left\{e(x) \left[ie_a^\mu\gamma^a\left(\partial_\mu-\Omega_\mu\right)-m\right]\right\}^{-1}\\
=&-\left(i\slashed{\partial}-m\right)^{-1}\left\{\left(e(x) \left[ie_a^\mu\gamma^a\left(\partial_\mu-\Omega_\mu\right)-m\right]-\left[i\slashed{\partial}-m\right]\right)\left(i\slashed{\partial}-m\right)^{-1}+1\right\}^{-1}\\
=&-\left(i\slashed{\partial}-m\right)^{-1}+\left(i\slashed{\partial}-m\right)^{-1}\left\{e(x) \left[ie_a^\mu\gamma^a\left(\partial_\mu-\Omega_\mu\right)-m\right]-\left[i\slashed{\partial}-m\right]\right\}\left(i\slashed{\partial}-m\right)^{-1}+\dots
\end{align}
Performing integration by parts and changing order of $\Omega$ and $\gamma$ using commutation relations, one finds
\begin{multline}
S_g(x_1,x_2)=
S(x_1-x_2)+\int d^4xS(x_1-x)\left\{\frac{i}{2}e(x)e_a^\mu\gamma^a\left(\overrightarrow{\partial}_\mu-\Omega_\mu\right) -\frac{i}{2}\left(\overleftarrow{\partial}_\mu+\Omega_\mu\right)e(x)e_a^\mu\gamma^a\right.\\
\left.-e(x)m-\left(i\overrightarrow{\slashed{\partial}}-m\right)\right\}S(x-x_2)+\dots
\end{multline}
Expanding the frame field using formula~\eqref{tetrad_expansion}, one finds
\begin{multline}
S_g(x_1,x_2)=
S(x_1-x_2)+\int d^4xS(x_1-x)\left\{\frac{i}{2}\delta e_a^\mu\gamma^a\overrightarrow{\partial}_\mu-\frac{i}{2}\overleftarrow{\partial}_\mu\gamma^a\delta e_a^\mu-\delta_\mu^a \left(\frac{i}{2}\delta e_a^\mu\overrightarrow{\slashed{\partial}}-\frac{i}{2}\overleftarrow{\slashed{\partial}}\delta e_a^\mu-m\delta e_a^\mu\right)\right.\\
\left.-\frac{i}{2}\delta_a^\mu\left(\gamma_a\delta\Omega_\mu+\delta\Omega_\mu\gamma_a\right)\right\}S(x-x_2)+\dots
\end{multline}
Using Eqs.~\eqref{connection},~\eqref{spin_connection} and integrating by parts once again, one obtains Eq.~\eqref{propagator_expansion}.

\subsection{Nonlocal vertex}
Consider the operator
\begin{equation}
\exp\left(\overleftarrow{D}\xi\frac{y}{\Lambda}\right)i\gamma_5 M^a \exp\left(-\overrightarrow{D}\xi'\frac{y}{\Lambda}\right)
\end{equation}
that appears in Eq.~\eqref{nonlocal_current_g}. The exponential of an operator $A$ can be defined as
\begin{equation}
\exp A=\lim_{n\to\infty}\prod_{i=1}^n \exp \frac{A}{n}.
\end{equation}
Consequently, the expansion in small $\delta A$ can be written in the form
\begin{equation}
\label{exp_expansion}
\exp \left(A+\delta A\right)=\exp A+\lim_{n\to\infty}\sum_{j=1}^n \exp \frac{jA}{n}\ \delta A\ \exp\frac{(n-j)A}{n}+\dots
\end{equation}
Using formula~\eqref{exp_expansion}, properties of the shift operator $\exp a\partial$ and taking the limit, one finds
\begin{align}
\exp\left(\overleftarrow{D}\xi\frac{y}{\Lambda}\right)=&\exp\left(\overleftarrow{\partial}\xi\frac{y}{\Lambda}\right)+\int_0^1d\tau\xi y^a\exp\left(\overleftarrow{\partial}\xi\frac{y}{\Lambda}\right)\left[\overleftarrow{\partial}_\mu \delta e_a^\mu\left(x+\tau\xi \frac{y}{\Lambda}\right)+ \delta_a^\mu\delta\Omega_\mu\left(x+\tau\xi \frac{y}{\Lambda}\right)\right]+\dots,\\
\exp\left(-\overrightarrow{D}\xi'\frac{y}{\Lambda}\right)=&\exp\left(-\overrightarrow{\partial}\xi'\frac{y}{\Lambda}\right)-\int_0^1d\tau \xi' y^a\left[\delta e_a^\mu\left(x-\tau\xi' \frac{y}{\Lambda}\right)\overrightarrow{\partial}_\mu- \delta_a^\mu\delta\Omega_\mu\left(x-\tau\xi' \frac{y}{\Lambda}\right)\right]\exp\left(-\overrightarrow{\partial}\xi\frac{y}{\Lambda}\right)+\dots
\end{align}
Now, using formula~\eqref{spin_connection} to expand $\delta\Omega_\mu$, Fourier transformation of $\delta e_a^\mu$ and definition of the vertex $V$ in Eq.~\eqref{current_flat_definition}, one can write the expansion of $V_g$ given by formula~\eqref{vertex_g_expansion}.

\section{Expressions for diagrams\label{appendix_diagrams_expressions}}
It is convenient to introduce shorthand notations for Eqs.~\eqref{propagator_expansion} and~\eqref{vertex_g_expansion}:
\begin{gather}
S_g(x_1,x_2)=S(x_1-x_2)+\int d^4x\delta e^{a\mu}(x)\delta_a^\nu S(x_1-x)\mathcal{O}_{\mu\nu}(x) S(x-x_2)+\dots,
\\
\bar{q}(x)V_g(x)q(x)=\bar{q}(x)V^{(0)}\left(x\right)q(x)+\int d^4z \delta e^{a\mu}(z)\delta_a^\nu \bar{q}(x)V_{\mu\nu}^{(1)}\left(x-z\right)q(x)\dots
\end{gather}
Then contributions of the diagrams in Fig.~\ref{figure_ppg} to the matrix element~\eqref{matrix_element} can be written as
\begin{equation}
\langle p'|T_{\mu\nu}(z)|p\rangle=(\text{a})+(\text{b})+(\text{c})+(\text{d})+(\text{e}),
\end{equation}
where the summands are given by
\begin{gather}
\tag{a}
\delta_{\mu\nu}\exp\left[i(p'-p)z\right]h^2M_0,\\
\tag{b}
\begin{split}
\int d^4x\exp(-ipx)\int d^4x\exp(ip'x')(-1)h^2&\left\{-\delta_{\mu\nu}\delta^{(4)}(x-z)\mathrm{Tr}V^{(0)}(x)S(x-x')V^{(0)}(x')S(x'-x)\right.\\
&\hphantom{\{}\left.+\mathrm{Tr}V_{\mu\nu}^{(1)}(x-z)S(x-x')V^{(0)}(x')S(x'-x)\right\},
\end{split}\\
\tag{c}
\begin{split}
\int d^4x\exp(-ipx)\int d^4x\exp(ip'x')(-1)h^2&\left\{-\delta_{\mu\nu}\delta^{(4)}(x'-z)\mathrm{Tr}V^{(0)}(x)S(x-x')V^{(0)}(x')S(x'-x)\right.\\
&\hphantom{\{}\left.+\mathrm{Tr}V^{(0)}(x)S(x-x')V_{\mu\nu}^{(1)}(x'-z)S(x'-x)\right\},
\end{split}\\
\tag{d}
\begin{split}
\int d^4x\exp(-ipx)\int d^4x\exp(ip'x')(-1)h^2\mathrm{Tr}V^{(0)}(x)S(x-x')V^{(0)}(x')S(x'-z)\mathcal{O}_{\mu\nu}(z)S(z-x),
\end{split}\\
\tag{e}
\begin{split}
\int d^4x\exp(-ipx)\int d^4x\exp(ip'x')(-1)h^2\mathrm{Tr}V^{(0)}(x)S(x-z)\mathcal{O}_{\mu\nu}(z)S(z-x')V^{(0)}(x')S(x'-x).
\end{split}
\end{gather}
The terms proportional to $\delta_{\mu\nu}$ originate from the expansion of $e(x)$.

The explicit expressions are most conveniently obtained using Schwinger representation of propagators
\begin{equation}
S(x-y)= \int_0^\infty ds \int \frac{d^4p}{(2\pi)^4} \exp\left[  - (p^2+m^2) s - ip(x-y)\right]\\
\left( p_\mu\gamma_\mu  + m \right).
\end{equation}
The traces over flavor color are trivial in one-loop case, and the trace over products of Dirac matrices can be evaluated in a computer algebra system such as FORM~\cite{Ruijl:2017dtg}.
The result of action of vertex operators $V$ can be found using
\begin{equation*}
\exp(ipx)\int_0^1 dt \exp\left\{\left(\frac{\overleftrightarrow{\partial}}{\Lambda}\right)^2t\right\}\exp(-iqx)=\exp(ipx)\int_0^1 dt \exp\left\{-\frac{(\xi p+\xi'q)^2}{\Lambda^2}t\right\}\exp(-iqx)
\end{equation*}
which can be deduced from Eq.~\eqref{current_flat_definition}. The momentum integrals become Gaussian and can be evaluated analytically. Then the remaining integrals over proper times originating from the propagators and vertices can be evaluated numerically.
