	Two standard examples we will be referring to frequently are the standard simplex and the horn. The \emph{standard $m$-simplex} $\Delta^m$ is given by $(\Delta^m)_k \coloneqq \{ f: [k] \rightarrow [m] \text{ } \vert \text{ } f(i) \leq f(j) \text{ for all }  0\leq i\leq j\leq k \}$ (see Fig.\ref{fig1a}). The \emph{horn} $\Lambda^m_j$ on the other hand is given by $(\Lambda^m_j)_k \coloneqq \{ f \in (\Delta^m)_k \vert \{0, \dots, j-1, j+1, \dots, m \} \nsubseteq \{f(0), \dots, f(k) \} \}$ (see Fig.\ref{fig1b}). In general, we can think of the horn as removing the highest non-degenerate face as well as the face opposite the $j$-th vertex from a simplex. Note that from the definition, $\Delta^m$ and $\Lambda^m_j$ are only simplicial sets, but endowed with the discrete topology, these can be viewed as simplicial manifolds. 

	The (higher) group(oid) structure (based on Duskin's definition of higher group(oid)s, cf. \cite{duskin1979higher}) on these simplicial manifolds is then given in the form of Kan conditions. These describe whether any horn in $X_{\bullet}$ can be (uniquely) filled to a simplex. In the diagram below, the existence of such a (unique) filling can be described in terms of the \emph{horn projection}
	\begin{equation}\label{hornproj}
		p^m_j: \mbox{Hom}(\Delta^m, X_{\bullet}) \rightarrow \mbox{Hom}(\Lambda^m_j, X_{\bullet}).
	\end{equation}
	We say that $X_{\bullet}$ satisfies the Kan condition $\mbox{Kan}(m,j)$ iff any horn $\Lambda^m_j$ in $X_{\bullet}$ can be filled to a simplex $\Delta^m$ in $X_{\bullet}$. Equivalently, $p^m_j$ is a surjective submersion. Further, we say that $X_{\bullet}$ satisfies the strict Kan condition $\mbox{Kan!}(m,j)$, iff this horn filling is unique. Equivalently, $p^m_j$ is a diffeomorphism.

	\begin{center}
		\begin{tikzcd}
			\Lambda^m_j \arrow{r}{} \arrow[hookrightarrow, swap]{d}{} 
			& X_{\bullet}\\
			\Delta^m \arrow[dashed, swap]{ur}{\exists lift? (*)}&
		\end{tikzcd}\\
	\end{center}

\begin{definition}\label{n-gpd}
	A \emph{Lie $n$-groupoid} $X_{\bullet}$ is a simplicial manifold that satisfies:
	\begin{enumerate}
		\item $\mbox{Kan}(m,j)$ for all $m\geq 1$ and $0\leq j\leq m$.
		\item $\mbox{Kan!}(m,j)$ for all $m\geq n+1$ and $0\leq j\leq m$.
	\end{enumerate}
	A Lie $n$-group is a Lie $n$-groupoid $X_{\bullet}$ where $X_0 = \mbox{pt}$.
\end{definition}

\begin{example}\label{Ep_Liegpd}
	Given a Lie groupoid $G_1 \rightrightarrows G_0$, the simplicial nerve of this groupoid, consisting at the $k$-th level of chains of $k$ composable morphisms, has the following form:
	\begin{equation}
	\dots G_1 \times_{G_0} G_1 \rrrarrows G_1 \rightrightarrows G_0.
	\end{equation}
	This is a (simplicial) Lie $1$-groupoid together with $d_{0}(g) = s(g)$, $d_{1}(g) = t(g)$ $\forall g\in G_1$ and higher face maps consist of composing the morphisms at position $i$ and $i+1$, while the degeneracy maps simply insert a unit morphism at the $i$-th position. The Kan conditions from Definition (\ref{n-gpd}) then come from the Lie groupoid axioms of $G_{\bullet}$. If we start with a Lie group $G$ instead, we can do the same construction for the groupoid $G \rightrightarrows \mbox{pt}$. Then, we get the Lie $1$-groupoid
	\begin{equation}
	\dots G \times G \rrrarrows G \rightrightarrows \mbox{pt}.
	\end{equation}
