We will now briefly review the suitable notion of Lie $n$-groupoid morphisms. The morphisms we are interested in will be \emph{hypercovers}. But first, note that a morphism between simplicial objects consists of levelwise morphisms commuting with face and degeneracy maps. Equivalently, one can consider the simplicial objects as functors and morphisms between them as natural transformations. Kan conditions for such a morphism $f: X_{\bullet}\rightarrow Y_{\bullet}$ mean that there exists a (unique) horn-filling for a given level in $X_{\bullet}$ in such a way that it is compatible with $f$. This is depicted in the following diagram: 

\begin{center}
	\begin{tikzcd}[column sep=large, row sep=huge]
		\Lambda^m_j \arrow{r}{\varphi} \arrow[hookrightarrow]{d}{i} 
		& X_{\bullet} \arrow{d}{f} \\
		\Delta^m \arrow[dashed, swap]{ur}{\exists \phi ? (*)} \arrow{r}{\psi}
		& Y_{\bullet}
	\end{tikzcd}\\
\end{center}

We say that $f$ satisfies the Kan condition $\mbox{Kan}(m,j)$, if for any $\varphi, \psi$ as above there exists a lift $\phi$ such that $\phi \circ i = \varphi$ and $f\circ \phi = \psi$. If the lift is also unique, we say that $f$ satisfies the strict Kan condition $\mbox{Kan!}(m,j)$. Note that the unique simplicial morphism $f: X_{\bullet} \rightarrow \mbox{pt}_{\bullet}$ satisfies $\mbox{Kan}(m, j)$ iff $X_{\bullet}$ satisfies $\mbox{Kan}(m,j)$.

\begin{definition}\label{Kanfib}
	A simplicial morphism $f: X_{\bullet} \rightarrow Y_{\bullet}$ between simplicial manifolds $X_{\bullet}$ and $Y_{\bullet}$ is a \emph{Kan fibration} if $f$ satisfies $\mbox{Kan}(m\geq 1, j)$ for all $0\leq j \leq m$.\\
	A simplicial morphism $f: X_{\bullet} \rightarrow Y_{\bullet}$ between Lie $n$-groupoids is a \emph{Lie $n$-groupoid Kan fibration} if $f$ satisfies $\mbox{Kan}(m\geq 1, j)$ for all $0\leq j \leq m$ and $\mbox{Kan!}(m\geq n, j)$ for all $0\leq j\leq m$.
\end{definition}

	Another way to write this Kan condition for morphisms is by viewing $\mbox{Hom}(\Delta[m], X_{\bullet})$ as $X_m$ and considering
	\begin{equation}
	p_j^m: X_m \rightarrow \mbox{Hom}(\Lambda^m_j, X_{\bullet}) \times_{\mbox{Hom}(\Lambda^m_j, Y_{\bullet})} \mbox{Hom}(\Delta^m, Y_{\bullet}).
	\end{equation}
	\begin{enumerate}
		\item $\mbox{Kan}(m,j)$ holds for $f$ iff $p_j^m$ is a surjective submersion and
		\item $\mbox{Kan!}(m,j)$ holds for $f$ iff $p_j^m$ is a diffeomorphism. % Check surj + isom vs ss + diffeo
	\end{enumerate}
	Note that for $Y_{\bullet} = \mbox{pt}$, this map becomes $p^m_j : X_m \rightarrow \mbox{Hom}(\Lambda^m_j, X_{\bullet})$ from Eq.~(\ref{hornproj}) in Definition (\ref{n-gpd}), so $X_{\bullet}$ is a Lie $n$-groupoid iff $f: X_{\bullet} \rightarrow \mbox{pt}$ is a Lie $n$-groupoid Kan fibration.

Definition (\ref{Kanfib}) gives us a suitable notion of morphisms between Lie $n$-groupoids. However, this concept is not quite enough to give us a notion of Morita equivalence. Hence, we need to define a stronger version of morphisms (which will correspond to \emph{acyclic} fibrations).

\begin{definition}\label{hypercover}
	A simplicial morphism $f: X_{\bullet} \rightarrow Y_{\bullet}$ of Lie $n$-groupoids is a \emph{hypercover} if the maps
	\begin{equation}\label{q_m}
	q_m \coloneqq ((d_0, \dots, d_m), f_m): X_m \rightarrow \mbox{Hom}(\partial \Delta^m, X_{\bullet}) \times_{\mbox{Hom}(\partial \Delta^m, Y_{\bullet})} Y_m
	\end{equation}
	are surjective submersions for $0\leq m \leq n-1$ and a diffeomorphism for $m=n$. This automatically gives that $q_m$ is a diffeomorphism for $m > n$.
\end{definition}

	Here, $\partial \Delta^m$ denotes the boundary of the simplex $\Delta^m$. The existence of the pullbacks $ \mbox{Hom}(\partial \Delta^m, X_{\bullet}) \times_{\mbox{Hom}(\partial \Delta^m, Y_{\bullet})} Y_m$ was proven in Lemma 2.4 of \cite{zhu2009stacky} using induction. Note that $q_0 = f_0$ above is a surjective submersion. In the special case $n=1$, Defintion (\ref{hypercover}) recovers the definition of a hypercover between Lie groupoids $G_{\bullet}$ and $H_{\bullet}$, as
	\begin{equation}
	q_1 = ((d_0, d_1), f_1) = ((s, t), f_1) : G_1 \rightarrow (G_0 \times G_0) \times_{H_0 \times H_0} H_1
	\end{equation}
	is an isomorphism. This means that our definition of Morita equivalence between Lie $n$-groupoids will be a generalization of Morita equivalence between Lie groupoids. When dealing with hypercovers in the later sections of this article, we will need the following proposition.

\begin{proposition}\label{hypercoverfib}
	Let $f: X_{\bullet} \rightarrow Y_{\bullet}$ be a hypercover between Lie $n$-groupoids. Then, the levelwise maps $f_m: X_m \twoheadrightarrow Y_m$ are surjective submersions.
	\begin{proof}
		For $f_0: X_0 \twoheadrightarrow Y_0$, this follows immediately from the definition as $q_0 = f_0$. The general statement can then be proven using a trick from Proposition (6.5) in \cite{del2024cohomology}, which also appeared in similar forms in \cite{henriques2008integrating} and \cite{wolfson2016descent} and uses a filtration
		\begin{equation}
		S_0 = \emptyset \hookrightarrow \mbox{pt} \hookrightarrow \dots \hookrightarrow \coprod_{i=1}^{n} \mbox{pt} \hookrightarrow \dots \hookrightarrow \partial \Delta^n \hookrightarrow S_k = \Delta^n,
		\end{equation}
		where each step is the adjunction of a cell, i.e.~$S_l \cong S_{l-1} \cup_{\partial \Delta^{n_l}} \Delta^{n_l}$, to construct the pullback diagrams
		\begin{center}
			\begin{tikzcd}
				\mbox{Hom}(S_l, X_{\bullet}) \times_{\mbox{Hom}(S_l, Y_{\bullet})} Y_n \arrow[twoheadrightarrow]{r}{g_l} \arrow{d}{}
				& \mbox{Hom}(S_{l-1}, X_{\bullet}) \times_{\mbox{Hom}(S_{l-1}, Y_{\bullet})} Y_n \arrow{d}{}\\
				X_{n_l} \arrow[twoheadrightarrow]{r}{q_{n_l}} 
				& \mbox{Hom}(\partial \Delta^{n_l}, X_{\bullet}) \times_{\mbox{Hom}(\partial \Delta^{n_l}, Y_{\bullet})} Y_{n_l}
			\end{tikzcd}
		\end{center}
		Since $q_{n_l}$ from (\ref{q_m}) is a surjective submersion, so is $g_l$ and thus the composition $f_n = g_k \circ \dots \circ g_1$ is a surjective submersion.
	\end{proof}
\end{proposition}

\begin{definition}\label{ME}
	Two Lie $n$-groupoids $X_{\bullet}$ and $Y_{\bullet}$ are Morita equivalent if there exists a Lie $n$-groupoid $Z_{\bullet}$ and a zig-zag of hypercovers
	\begin{center}
		\begin{tikzcd}
			& Z_{\bullet} \arrow[swap, twoheadrightarrow]{dl}{f} \arrow[twoheadrightarrow]{dr}{g} & \\
			X_{\bullet} & & Y_{\bullet}
		\end{tikzcd}\\
	\end{center}
\end{definition}

Note that this relation is indeed an equivalence relation, as follows in particular from Proposition (\ref{equivrel}) later on.

