To define the tangent complex, we will use Definition 2.8 in \cite{cuecazhu2023shiftedsymplectic}

\begin{definition}\label{tangentcx}
	Let $X_{\bullet}$ be a Lie $n$-groupoid. We define the \emph{tangent complex} $(\mathcal{T}_{\bullet}X, \partial)$ as the following complex of vector bundles over $X_0$:
	\begin{equation}
	\mathcal{T}_l X \coloneqq
	\begin{cases}
	\mbox{ker} (T p^l_l) \vert_{X_0} & \text{for } l>0,\\
	TX_0 & \text{for } l=0,\\
	0 & \text{for } l<0,
	\end{cases}
	\end{equation}
	with $\partial \coloneqq (-1)^{l} Td_{l}^{l}$. Here, $p^l_l$ is the horn projection from Eq.~(\ref{hornproj}) used in Definition (\ref{n-gpd}). We write $H_{\bullet}(\mathcal{T}X)$ for the \emph{homology groups} of the tangent complex $(\mathcal{T}_{\bullet}X, \partial)$.
\end{definition}

	As proven in Propositon 2.10 in \cite{cuecazhu2023shiftedsymplectic}, for $X_{\bullet}$ a Lie $n$-groupoid and $l\geq 0$, we get an isomorphism
	\begin{equation}
	\mathcal{T}_{l}X \cong TX_{l}\vert_{X_0} / \oplus_{i=0}^{l-1} \hbox{im}(Ts_{i}^{l-1}),
	\end{equation}
	sending $\partial$ to $\sum_{i=0}^{l} (-1)^{i} Td_{i}^{l}$. Additionally, we get $\mathcal{T}_{l}X = 0$ for $l>n$ since $p_{l,l}$ is an isomorphism in those cases. This tangent complex has been proven to be invariant up to weak equivalence under Morita equivalence of Lie $n$-groupoids (cf.~Corollary 2.28 in \cite{cuecazhu2023shiftedsymplectic}) and to have the structure of the corresponding Lie $n$-algebroid (cf.~\cite{li2023differentiating}), hence this is the correct notion of tangent complex for our setting. We can see this in an example for the case $n=1$.

\begin{example}\label{Ep_Liealgbd}
	Let $G \rightrightarrows M$ be a Lie groupoid as in Example (\ref{Ep_Liegpd}). Then, its simplicial nerve $NG_{\bullet}$ is the Lie $1$-groupoid 
	\begin{equation}
	\dots G \times_{M} G \rrrarrows G \rightrightarrows M
	\end{equation}
	with face maps $d^2_0 = \mbox{pr}_1$, $d^2_1 = m$, and $d^2_2 = \mbox{pr}_2: G \times_{M} G \rightarrow G$ on the second level as well as $d^1_0 = s$ and $d^1_1 = t: G \rightarrow M$ on the first level. The degeneracy $s^0_0 : M \rightarrow G$ is given as $m \mapsto \mbox{id}_m$. The corresponding tangent complex from Definition (\ref{tangentcx}) thus has the form of its Lie algebroid $A = \mbox{ker}Ts\vert_{M}$,
	\begin{equation}
	\mathcal{T}_i G \coloneqq
	\begin{cases}
	A & \text{for } i=1,\\
	TM & \text{for } i=0,\\
	0 & \text{else},
	\end{cases}
	\end{equation}
	with $\partial = \rho: A \rightarrow TM$ given by the anchor $\rho = Tt\vert_{A}$.
\end{example}

An important property we will need in the proof of the main theorem of this article is the following statement (see Lemma 2.27 in \cite{cuecazhu2023shiftedsymplectic}) that hypercovers between Lie $n$-groupoids induce isomorphisms on the homology groups of the corresponding tangent complexes. 

\begin{lemma}\label{hypercoverquasi}
	Let $f_{\bullet} : X_{\bullet} \rightarrow Y_{\bullet}$ be a hypercover of Lie $n$-groupoids. Then, the induced maps $Tf_l: \mathcal{T}_lX \rightarrow \mathcal{T}_lY$ form a quasi-isomorphism (i.e.~an isomorphism on the homology groups).
	\begin{proof}
		A detailed proof of this statement is provided in \cite{cuecazhu2023shiftedsymplectic}.
	\end{proof}
\end{lemma}

	As done in \cite{cuecazhu2023shiftedsymplectic} and \cite{getzlerslides}, we can define the \emph{de Rham simplicial double complex} (also known as the \emph{Bott-Shulmann-Stasheff double complex}) $(\Omega^{\bullet}(X_{\bullet}), d, \delta)$ for any simplicial manifold $X_{\bullet}$, where $\Omega^{q}(X_{p})$ denotes the differential $q$-forms on the manifold $X_p$, equipped with the usual \emph{de Rham differential} $d: \Omega^{q}(X_{p}) \rightarrow \Omega^{q+1}(X_{p})$ and the \emph{simplicial differential} $\delta: \Omega^{q}(X_{p-1}) \rightarrow \Omega^{q}(X_{p})$ given as $\delta = \sum_{i=0}^{p} (-1)^{i} d_{i}^{*}$. The total complex given by $\Omega^n \coloneqq \bigoplus_{p+q=n} \Omega^{q}(X_{p})$ with differential $D = \delta + (-1)^{p} d$ gives us a notion of differential forms on simplicial manifolds. 

	\begin{center}
		\begin{tikzcd}
			\vdots
			& \vdots
			& \vdots & \\
			\Omega^{2}(X_{0}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{2}(X_{1}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{2}(X_{2}) \arrow{r}{\delta} \arrow{u}{d}
			& \dots \\
			\Omega^{1}(X_{0}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{1}(X_{1}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{1}(X_{2}) \arrow{r}{\delta} \arrow{u}{d}
			& \dots \\
			\Omega^{0}(X_{0}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{0}(X_{1}) \arrow{r}{\delta} \arrow{u}{d}
			& \Omega^{0}(X_{2}) \arrow{r}{\delta} \arrow{u}{d}
			& \dots
		\end{tikzcd}
	\end{center}

	To make calculations easier, we restrict to the sub-complex $\widehat{\Omega}^{\bullet}(X_{\bullet})$ of \emph{normalised differential forms}. A differential form $\alpha$ is called \emph{normalised} if it vanishes on degeneracies, i.e. 
	\begin{equation}
	\widehat{\Omega}^{\bullet}(X_{\bullet}) = \{  \alpha \in \Omega^{\bullet}(X_{\bullet}) \vert s_{i}^{*} \alpha = 0 \text{ for all (possible) } i \}.
	\end{equation}

	Additionally, when defining (normalised) $k$-forms on $X_{\bullet}$ as elements in the total complex $\widehat{\Omega}^k$, we will apply a filtration to cut off the components with $q<k$. As explained in \cite{getzlerslides}, this filtration was introduced in \cite{PTVV2013shifted} to be able to define closed forms in the proper way. In our case, this means that a (normalised) $m$-shifted $k$-form, i.e.~a form $\alpha_{\bullet} \in \widehat{\Omega}^{k+m}$ has components $\alpha_i \in \Omega^{k+m-i}(X_{i})$ with the highest component $\alpha_m$ being a $k$-form on $X_m$. In particular, this means that $\alpha_m$ is \emph{multiplicative}, i.e~$\delta \alpha_m = 0$. We will use the following definition of an $m$-shifted $k$-form from \cite{cuecazhu2023shiftedsymplectic}, which matches the constructions of (twisted) symplectic groupoids in the case $n=1$:

\begin{definition}\label{presympl}
	Let $X_{\bullet}$ be a simplicial manifold. An \emph{$m$-shifted $k$-form} $\alpha_{\bullet}$ on $X_{\bullet}$ is of the form
	\begin{equation}
	\alpha_{\bullet} = \sum_{i=0}^{m} \alpha_i \text{ with } \alpha_i \in \widehat{\Omega}^{k+m-i}(X_{i}).
	\end{equation}
	Such a form $\alpha_{\bullet}$ is called \emph{closed} if $D\alpha_{\bullet} = 0$. 
	We say that a closed normalised $m$-shifted $2$-form $\alpha_{\bullet}$ on $X_{\bullet}$ is an \emph{$m$-shifted presymplectic form} on $X_{\bullet}$. 
\end{definition}

	As is expressed in the name \emph{presymplectic} form, we now have almost all of the ingredients we need to define shifted symplectic forms on Lie $n$-groupoids in Definition (\ref{presympl}). We have a concept of (normalised) $m$-shifted $k$-forms, in particular $m$-shifted $2$-forms, and we can also ascertain whether such a form is closed or not. The only property we are missing is the non-degeneracy of such a form. This, however, is more difficult to define in this generalized setting. Usually, when dealing with a presymplectic form $\omega_{\bullet} \in \Omega^2(X)$ on a manifold $X$, we would consider the associated map $\omega_{\bullet}^{\flat}: T X \rightarrow T^{*}X$ between the tangent and the cotangent bundle and check whether this is an isomorphism. In our case, the $2$-form $\omega_m \in \Omega^2(X_m)$ yields a map $\omega_m^{\flat}: TX_m \rightarrow T^{*}X_m$. This only acts on the tangent bundle. What we need, however, is a quasi-isomorphism between the tangent complex $\mathcal{T}X$ and the cotangent complex $\mathcal{T}^{*}X$ given as $\mathcal{T}_l^{*}X \coloneqq (\mathcal{T}_{-l}X)^{*}$ with differential $\partial^{*} \coloneqq \partial^t$ the transpose. Equivalently (cf.~\cite{del2020morita}), we want a pairing on the tangent complex that descends to a non-degenerate pairing on the homology groups. Taking the normalisation functor to move to the Moore complex does not work here, as the functor does not commute with the pairing. For this, we need to use the Eilenberg-Zilber isomorphism to get a pairing on the Moore complex. Because this pairing then takes place on the Lie $n$-algebroid corresponding to $X_{\bullet}$ instead of the tangent spaces themselves, the resulting pairing turns out to come from something called the \emph{infinitesimal multiplicative form} (or \emph{IM-form}) $\lambda^{\omega_{\bullet}}$ corresponding to $\omega_{\bullet}$. For the general case of a Lie $n$-groupoid, we will use an explicit formula for this IM-form that has been proven to have all of the properties we need (cf. \cite{cuecazhu2023shiftedsymplectic}). But to further motivate where this construction comes from, we will first take a look at the case $n=1$, which has been studied for a long time already and where the IM-form has been a known entity.

\begin{example}\label{Ep_twistedsympl}
	Let $G \rightrightarrows M$ be a Lie groupoid and let $\omega \in \Omega^{2}(G)$ be a $2$-form on $G$ and let $\phi \in \Omega^{3}(M)$ be a closed $3$-form on $M$, i.e.~$d\phi = 0$. $\omega$ is called \emph{relatively $\phi$-closed} if $d\omega = s^{*}\phi - t^{*}\phi$ (cf.~\cite{BCWZ2004dirac}) and $\omega$ is called \emph{multiplicative} if $m^{*}\omega = \mbox{pr}_1^{*}\omega + \mbox{pr}_2^{*}\omega$ as before. Considering the simplicial nerve $NG_{\bullet}$ of the Lie groupoid $G\rightrightarrows M$ as done in Example (\ref{Ep_Liegpd}), these conditions simply translate to 
	\begin{align}
	d\phi &= 0; \\
	d\omega &= \delta \phi;\\
	\delta \omega &= 0.
	\end{align}
	Hence, we get a closed $1$-shifted $2$-form $\omega_{\bullet} = \omega + \phi$ on the Lie $1$-groupoid $NG_{\bullet}$. If $\omega_{\bullet}$ is normalised, this is a $1$-shifted presymplectic form. If $\omega$ is non-degenerate, this becomes the definition of a $\phi$-twisted symplectic groupoid from \cite{BCWZ2004dirac}, which is also known as a quasisymplectic groupoid in \cite{xu2004momentum}.\\ %Check details?
	Given a relatively $\phi$-closed multiplicative $2$-form $\omega$ as above, we can construct a vector bundle map $\sigma: A \rightarrow T^{*}M$ satisfying
	\begin{align}
	&\sigma(u)(\rho(v)) = - \sigma(v)(\rho(u));\\
	&\sigma([u,v]) =  \mathcal{L}_{\rho(u)} \sigma(v) - i_{\rho(v)} d\sigma(u) + i_{\rho(v)} i_{\rho(u)} \phi % Check details?
	\end{align}
	for all $u,v \in \Gamma(A)$ (cf.~\cite{BCWZ2004dirac}). A vector bundle map satisfying these conditions is called an \emph{IM-form} (cf.~\cite{bursztyn2009linear}). The IM-form corresponding to $\omega$ is given as $\sigma(u) = i_{u}\omega\vert_{TM}$ for all $u\in A$. If $G$ is $s$-simply connected over $M$, the correspondence between relatively $\phi$-closed multiplicative $2$-forms $\omega$ and IM-forms $\sigma$ is one-to-one (cf.~\cite{BCWZ2004dirac}).\\ 
	Another way to look at this construction is via the fact that a $2$-form on a Lie groupoid $G \rightrightarrows M$ is multiplicative iff the bundle map $\omega^{\flat}: TG \rightarrow T^{*}G$ is a Lie groupoid morphism (cf.~\cite{bursztyn2009linear}). A similar statement is also true for general multiplicative $k$-forms (cf.~\cite{bursztyn2012multiplicative}). By applying the Lie functor, multiplicative $k$-forms on Lie groupoids correspond naturally to linear infinitesimal multiplicative forms $\Lambda \in \Omega^{2}(A)$ on the total space of the corresponding Lie algebroid $A$. The condition that $\Lambda$ is infinitesimal multiplicative is equivalent to saying that $\Lambda^{\flat}: TA \rightarrow T^{*}A$ is a Lie algebroid map covering $\lambda = -\sigma^{t}: TM \rightarrow A^{*}$ (cf.~\cite{bursztyn2012multiplicative}). In the case $k=2$ and if $\omega$ is relatively $\phi$-closed, $\Lambda$ can be constructed via vector bundle maps The corresponding linear infinitesimal multiplicative form $\Lambda \in \Omega^{2}(A)$ can then be written as $\Lambda = -(\sigma^{*}\omega_{can} + \rho^{*} \tau(\phi))$ where $\omega_{can}$ is the canonical symplectic form on $T^{*}M$ and $\tau(\phi) \in \Omega^{2}(TM)$ is given pointwise as $\tau(\phi)_{X} = \mbox{pr}_{M}^{*}(i_{X} \phi)$ for $X\in TM$ and the natural projection $\mbox{pr}_M : TM \rightarrow M$ (cf.~\cite{bursztyn2009linear}). In this case, we get the following maps between the tangent and the cotangent complex of $G\rightrightarrows M$ as constructed in Example (\ref{Ep_Liealgbd}):
	\begin{center}
		\begin{tikzcd}
			A \arrow[swap]{d}{\sigma} \arrow{r}{\rho} 
			& TM \arrow{d}{\lambda}\\
			T^{*}M \arrow[swap]{r}{\rho^{*}} 
			& A^{*}
		\end{tikzcd}
	\end{center} % Write down maps in detail to compare with later?
	For detailed proofs, see \cite{BCWZ2004dirac}, \cite{bursztyn2009linear}, and \cite{bursztyn2012multiplicative}.
\end{example} % More on non-deg conditions and dimensions?

For the general case of an $m$-shifted presymplectic form $\omega_{\bullet}$ on a Lie $n$-groupoid $X_{\bullet}$, we can now define the corresponding IM-form $\lambda^{\omega_{\bullet}}$ as done in \cite{cuecazhu2023shiftedsymplectic} by using an explicit formula from \cite{getzlerslides}. Afterwards, we will look at some of the properties this IM-form has and use them to define the non-degeneracy condition.

\begin{definition}\label{IM_form}
	Let $X_{\bullet}$ be a Lie $n$-groupoid with an $m$-shifted presymplectic form $\omega_{\bullet}$. For $l\in \Z$, $v \in (\mathcal{T}_{l}X)_{x} \subseteq T_xX_l$, and $w \in (\mathcal{T}_{m-l}X)_{x} \subseteq T_xX_{m-l}$ in the tangent complex at $x\in X_0$, we define a pointwise pairing (formula from \cite{getzlerslides}):
	\begin{equation}
	\lambda_{x}^{\omega_{\bullet}}(v,w) \coloneqq \sum_{\sigma \in \text{Shuff}_{l, m-l}} (-1)^{\sigma} \omega_{m}(T(s_{\sigma(m-1)} \dots s_{\sigma(l)})v, T(s_{\sigma(l-1)} \dots s_{\sigma(0)})w),
	\end{equation}
	where $\text{Shuff}_{l, m-l}$ denotes the $(l, m-l)$-shuffles and $(-1)^{\sigma}$ denotes the sign of the shuffle $\sigma$.
\end{definition}

\begin{remark}\label{IM_properties}
	The idea in Definition (\ref{IM_form}) is that by viewing $(\mathcal{T}_{l}X)_{x} \subseteq T_xX_l$ and $(\mathcal{T}_{m-l}X)_{x} \subseteq T_xX_{m-l}$, we can use the degeneracies to pull $v$ and $w$ up to $TX_m$, where we can apply the $2$-form $\omega_m$. This (highest term of the) IM-form concerning $\omega_m$ is enough to define a useful notion of non-degeneracy. To see this, let us quickly remark on some of the basic properties of this IM-form, which were first mentioned in \cite{getzlerslides} and proven in the Appendix of \cite{cuecazhu2023shiftedsymplectic}. From the definition, it can be checked that $\lambda^{\omega_{\bullet}}$ is graded anti-symmetric. Additionally, because $\omega_m$ is multiplicative, $\lambda^{\omega_{\bullet}}$ is \emph{infinitesimal multiplicative}, i.e.~for $u \in (\mathcal{T}_{l+1}X)$, and $w \in (\mathcal{T}_{m-l}X)$, we have
	\begin{equation}
	\lambda^{\omega_{\bullet}}(\partial u,w) + (-1)^{l+1} \lambda^{\omega_{\bullet}}(u,\partial w) = 0.
	\end{equation}
	This means that $\lambda$ respects the differential $\partial$ on the tangent complex, making it into a chain map which hence descends to the homology groups. Thus, we get a pairing
	\begin{equation}
	\lambda^{\omega_{\bullet}}(-,-) : H_l(\mathcal{T}X) \times H_{m-l}(\mathcal{T}X) \rightarrow \R_{X_0},
	\end{equation}
	where $\R_{X_0}$ denotes the trivial bundle over $X_0$. % More details on trivial bundle?
\end{remark}

Using this property, we will call an $m$-shifted $2$-form $\omega_{\bullet}$ \emph{non-degenerate} if this pairing on the level of homology is pointwise non-degenerate. This gives us the final building block to define shifted symplectic forms in the same way as in Definition 2.14 in \cite{cuecazhu2023shiftedsymplectic}.

\begin{definition}\label{shiftedsympl}
	A pair $(X_{\bullet}, \omega_{\bullet})$ is an \emph{$m$-shifted symplectic Lie $n$-groupoid} if $X_{\bullet}$ is a Lie $n$-groupoid and $\omega_{\bullet}$ is a closed, normalized, and non-degenerate $m$-shifted $2$-form on $X_{\bullet}$.
\end{definition}

% remark on possible values of m depending on n?
The following Examples (\ref{Ep_shiftedsymplmfd}) and (\ref{Ep_shiftedsymplgpd}) show that Definition (\ref{shiftedsympl}) recovers important special cases.

\begin{example}\label{Ep_shiftedsymplmfd}
	Let $M$ be a manifold. The simplicial nerve has the form
	\begin{equation}
	\dots M \rrrarrows M \rightrightarrows M
	\end{equation}
	with all the arrows being the identity (under identification of $m\in M$ with the arrow $\mbox{id}_m$). In this case, the tangent complex is concentrated only in degree $l=0$ with $\mathcal{T}_0 M = TM$ and $\mathcal{T}_l M = 0$ for all $l \neq 0$. Thus, we can only have a $0$-shifted symplectic structure in $M$. Let $\omega_{\bullet}$ be a $0$-shifted presymplectic form on $M$. This means that $\omega_{\bullet} = \omega \in \Omega^{2}(M)$ is closed, i.e.~$d\omega = 0$ and multiplicative, which in this case simply means $\mbox{id}^{*}\omega - \mbox{id}^{*}\omega = 0$ and thus is automatically satisfied. This makes sense since the algebraic structure on the unit groupoid is trivial. The IM-form corresponding to $\omega$ is given as
	\begin{equation}
	\lambda_x^{\omega}(v,w) = \omega(v, w),
	\end{equation}
	for $v, W \in \mathcal{T}_xM = T_xM$ and $x\in M$. The non-degeneracy condition is thus equivalent to the non-degeneracy of $\omega$, so a $0$-shifted symplectic Lie $0$-groupoid in Definition (\ref{shiftedsympl}) is the same as a classical symplectic manifold.
\end{example}

\begin{example}\label{Ep_shiftedsymplgpd}
	Let $G \rightrightarrows M$ be a Lie groupoid. As before, a $1$-shifted symplectic form in Definition (\ref{shiftedsympl}) on the nerve $NG_{\bullet}$ consists of $\omega_{\bullet} = \omega + \phi$ with $\omega \in \Omega^2(G)$ and $\phi \in \Omega^3(M)$ normalised, satisfying $\delta \omega = 0$, $d\omega = \delta \phi$, and $d\phi = 0$ such that the pairing induced by the IM-form $\lambda^{\omega_{\bullet}}$ is non-degenerate. The non-degeneracy in this case is equivalent to $\mbox{ker} \omega_x \cap A_x \cap \mbox{ker} \rho_x = 0$, $\forall x\in M$. (cf. \cite{cuecazhu2023shiftedsymplectic}). In total, this recovers the definition of a \emph{twisted presymplectic Lie groupoid} in \cite{BCWZ2004dirac} also known as a \emph{quasi-symplectic Lie groupoid} in \cite{xu2004momentum} as noted before. In this case, the IM-form $\lambda^{\omega_{\bullet}}$ has the form
	\begin{align}
	\lambda^{\omega_{\bullet}}(v,a) &= \pm \omega(Ts_0(v), a), \\
	\lambda^{\omega_{\bullet}}(a,v) &= \pm \omega(a, Ts_0(v)),
	\end{align}
	$\forall v\in (\mathcal{T}_0 G_{\bullet})_x = T_x M$, $a\in (\mathcal{T}_1 G_{\bullet})_x = A_x$. The induced pairing between the tangent complex and the cotangent complex then becomes:\\
	\begin{center}
		\begin{tikzcd}
			A_x \arrow[swap]{d}{\lambda^{\omega_{\bullet}}} \arrow{r}{\rho} 
			& T_x M \arrow{d}{\lambda^{\omega_{\bullet}}}\\
			(T_xM)^{*} \arrow[swap]{r}{\rho^{*}} 
			& (A_x)^{*}
		\end{tikzcd}
	\end{center}
	This matches the construction for the $n=1$ discussed in Example (\ref{Ep_twistedsympl}). In the case $\phi = 0$, we recover the classical notion of a \emph{symplectic groupoid} as defined in \cite{weinstein1987symplectic}. Note, however, that this notion is not invariant under Morita equivalence, which is why symplectic Morita equivalence only makes sense for shifted symplectic structures, as we will see in the next section.
\end{example}


