\begin{lemma}\label{retract}
	Let $A,B,C$ be (simplicial) manifolds. Let $\phi: C\rightarrow B$ be a morphism such that $\phi^{*}: \Omega^{\bullet}(B) \rightarrow \Omega^{\bullet}(C)$ is a quasi-isomorphism and let $f: A\rightarrow B$ be a retract of $\phi$, i.e.~there exist morphisms $g: C \rightarrow A$ and $s: A \rightarrow C$ such that $g\circ s = \mbox{id}$ and the following diagram commutes.
	\begin{center}
		\begin{tikzcd}
			& A \arrow[shift left]{dl}{s} \arrow[twoheadrightarrow]{dr}{f} & \\
			C \arrow[shift left]{ur}{g} \arrow{rr}{\phi} & & B
		\end{tikzcd}\\
	\end{center}
	Then, $f^{*}: \Omega^{\bullet}(B) \rightarrow \Omega^{\bullet}(A)$ is also a quasi-isomorphism.
	\begin{proof}
		Consider the following diagram on the level of cohomology
		\begin{center}
			\begin{tikzcd}
				H^{k}(A, \Omega^{\bullet}) \arrow{r}{g^{*}} \arrow[bend left=25]{rr}{\mbox{id}}
				& H^{k}(C, \Omega^{\bullet}) \arrow{r}{s^{*}} 
				& H^{k}(A, \Omega^{\bullet}) \\
				H^{k}(B, \Omega^{\bullet})  \arrow{r}{\mbox{id}} \arrow[swap]{r}{\cong}  \arrow{u}{f^{*}}
				& H^{k}(B, \Omega^{\bullet})  \arrow{r}{\mbox{id}} \arrow[swap]{r}{\cong}  \arrow{u}{\phi^{*}} \arrow[swap]{u}{\cong} 
				& H^{k}(B, \Omega^{\bullet}) \arrow{u}{f^{*}} \\
			\end{tikzcd}\\
		\end{center}
		From this diagram, we can see that $s^{*} \circ g^{*} = (g\circ s)^{*} = \mbox{id}$, hence $s^{*}$ must be surjective and $g^{*}$ must be injective. With this, we can conclude
		\begin{enumerate}
			\item $f^{*}$ is injective since $g^{*} \circ f^{*} = \phi^{*}$ is injective,
			\item $f^{*}$ is surjective since $f^{*} = s^{*} \circ \phi^{*}$ is surjective.
		\end{enumerate}
		This proves that $f^{*}: H^{k}(B, \Omega^{\bullet}) \xrightarrow{\sim} H^{k}(A, \Omega^{\bullet})$ is an isomorphism.
	\end{proof}
\end{lemma}

\begin{remark}
	Note that the de Rham functor $\Omega^{\bullet}$ is simply a placeholder here, as the same argument works for any cochain complexes on $A, B$ and $C$, as long as the morphisms between the objects induce cochain maps via their pullbacks.
\end{remark}


