\subsection{Experiment IV: High-Order Dynamics and Enriched NTK Structure  (forced vibration Equation)}\label{Exam:Vib}
% The evolution of hyper-parameters
% t = 1-5 cKAN failed and we dispersion 
% Decomposition in 5 parts (1 sec) 
% no dispersion ... 
% DONE ...

We now consider a forced vibration problem governed by the Euler–Bernoulli beam equation with damping. This example is used to highlight the structural complexity of the associated NTK matrix, which differs from previous cases due to the inclusion of higher-order temporal and spatial derivatives.
The governing equation is given by,
\begin{equation}
D_f \frac{\partial^4 u(x,t)}{\partial x^4} + c_d \frac{\partial u(x,t)}{\partial t} + \rho_l \frac{\partial^2 u(x,t)}{\partial t^2} = p(x,t), \quad (x,t) \in (0,l)\times (0,T],
\end{equation}
where $D_f$ is the flexural stiffness, $c_d$ is the damping coefficient, $\rho_l$ is the mass per unit length, $p$ is the external excitation force, and $u(x,t)$ is the displacement field.
This equation is subject to the following boundary and initial conditions,
\begin{equation}
    \begin{array}{ccc}
    \begin{cases}
u(0,t) = u(l,t) = 0, \\
\displaystyle\frac{\partial^2 u}{\partial x^2}(0,t) = \displaystyle\frac{\partial^2 u}{\partial x^2}(l,t) = 0,
\end{cases}
\quad t \in [0,T],     &   
\text{and}
&
\begin{cases}
u(x,0) = 0, \\
\displaystyle\frac{\partial u}{\partial t}(x,0) = 0,
\end{cases}
\quad x \in (0,l).
    \end{array}
\end{equation}

The parameters of the beam used in this example are as follows: $l = 1$ m, $\rho_l = 1$ kg/m, $D_f = 2$ N.m$^2$, $c_d = 3$ N.s/m$^2$. The excitation force is $p(x,t) = P \sin(\pi x/l)\cos(2 \pi f t)$, with an amplitude of $P=0.1$ N/m and a frequency of $f=2.7$ Hz. 

In contrast to the previous examples, the NTK matrix in this case includes additional diagonal blocks corresponding to the temporal derivative $u_t$ and the second-order spatial derivative $u_{xx}$, in addition to the standard terms $K_{uu}$ and $K_{rr}$. 
Within the physics-informed learning framework, we define the stacked network output $\boldsymbol{\psi}(\tau)$, the corresponding target vector $\boldsymbol{\mathcal{G}}$, and the associated NTK matrix $\boldsymbol{K}_{\text{ntk}}(\tau)$ in Eq.~\eqref{Eq:NTK100} as follows,
\begin{equation}\label{Eq:VibNTK}
    \begin{array}{ccc}
        \boldsymbol{\psi}(\tau) = \begin{bmatrix} 
    u(\boldsymbol{x}^d_i; \boldsymbol{\theta}(\tau)) \\
    u_t(\boldsymbol{x}^0_i; \boldsymbol{\theta}(\tau)) \\
    u_{xx}(\boldsymbol{x}^b_i; \boldsymbol{\theta}(\tau)) \\
    \mathcal{N}[u](\boldsymbol{x}^r_i; \boldsymbol{\theta}(\tau))
\end{bmatrix},
&  
\boldsymbol{\mathcal{G}} = \begin{bmatrix} 
    \boldsymbol{0} \\
    \boldsymbol{0} \\
    \boldsymbol{0} \\
    \boldsymbol{p}(\boldsymbol{x}^r_i)
\end{bmatrix},
&
\boldsymbol{K}_{\text{ntk}}(\tau) = 
\begin{bmatrix}
    K_{u,u} & K_{u,u_t} & K_{u,u_{xx}} & K_{u,r} \\
    K_{u_t,u} & K_{u_t,u_t} & K_{u_t,u_{xx}} & K_{u_t,r} \\
    K_{u_{xx},u} & K_{u_{xx},u_t} & K_{u_{xx},u_{xx}} & K_{u_{xx},r} \\
    K_{r,u} & K_{r,u_t} & K_{r,u_{xx}} & K_{r,r}
\end{bmatrix},
    \end{array}
\end{equation}
in which the  diagonal blocks are computed as inner products of gradients with respect to the model parameters,
\begin{equation}
\begin{array}{ll}
(K_{u,u})_{i,j} = \displaystyle{\left\langle \frac{\partial u(\boldsymbol{x}^d_i; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}}, \frac{\partial u(\boldsymbol{x}^d_j; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}} \right\rangle}, &
 (K_{u_{xx},u_{xx}})_{i,j} = \displaystyle{\left\langle \frac{\partial u_{xx}(\boldsymbol{x}^b_i; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}}, \frac{\partial u_{xx}(\boldsymbol{x}^b_j; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}} \right\rangle},\\[4mm] 
(K_{u_t,u_t})_{i,j} = \displaystyle{\left\langle \frac{\partial u_t(\boldsymbol{x}^0_i; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}}, \frac{\partial u_t(\boldsymbol{x}^0_j; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}} \right\rangle},&
(K_{r,r})_{i,j} = \displaystyle{\left\langle \frac{\partial \mathcal{N}[u](\boldsymbol{x}^r_i; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}}, \frac{\partial \mathcal{N}[u](\boldsymbol{x}^r_j; \boldsymbol{\theta}(\tau))}{\partial \boldsymbol{\theta}} \right\rangle}.
\end{array}
\end{equation}
leading to a larger and more structured NTK, capturing richer dynamics of the system and posing a more complex challenge for the learning process.
% This setup enables the use of the linearized training dynamics governed by the NTK to analyze how each physics constraint contributes to the learning process over training time $\tau$.


