\section{Proof of Theorem \ref{Theorem:NTKcKAN}}\label{App.Proof1}


% \subsection{Proof of Theorem \ref{Theorem:NTKcKAN}}
The Neural Tangent Kernel between two inputs $\boldsymbol{x}$ and $\boldsymbol{x}'$ is defined as the inner product of the gradients of the network output with respect to the parameters,
\begin{equation}\label{Eq:K_NTK_xx}
\begin{array}{cl}
    \boldsymbol{K}_{\text{ntk}}(\boldsymbol{x}, \boldsymbol{x}') & = \displaystyle{\left\langle \frac{\partial f(\boldsymbol{x}; \boldsymbol{\theta}(0))}{\partial \boldsymbol{\theta}}, \frac{\partial f(\boldsymbol{x}'; \boldsymbol{\theta}(0))}{\partial \boldsymbol{\theta}} \right\rangle} \\[4mm]
     & = \displaystyle{\sum_{i,j,n} \frac{\partial f(\boldsymbol{x}; \boldsymbol{\theta}(0))}{\partial w_{i,j,n}^{(1)}} \cdot \frac{\partial f(\boldsymbol{x}'; \boldsymbol{\theta}(0))}{\partial w_{i,j,n}^{(1)}} + \sum_{j,n} \frac{\partial f(\boldsymbol{x}; \boldsymbol{\theta}(0))}{\partial w_{j,1,n}^{(2)}} \cdot \frac{\partial f(\boldsymbol{x}'; \boldsymbol{\theta}(0))}{\partial w_{j,1,n}^{(2)}}}.
\end{array}
\end{equation}
Now, we simplify the NTK expression statistically, using the fact that the coefficients are i.i.d. standard normal,
\begin{equation}
 w_{i,j,n}^{(1)},\; w_{j,1,n}^{(2)} \sim \mathcal{N}(0, 1).
\end{equation}
We simplify the expected NTK,
\begin{equation}
    \mathbb{E}[\boldsymbol{K}_{\text{ntk}}(\boldsymbol{x}, \boldsymbol{x}')] = \mathbb{E}\left[K^{(1)}(\boldsymbol{x}, \boldsymbol{x}')\right] + \mathbb{E}\left[K^{(2)}(\boldsymbol{x}, \boldsymbol{x}')\right].
\end{equation}
where,
\begin{equation}
    K^{(1)}(\boldsymbol{x}, \boldsymbol{x}') = \displaystyle{\sum_{i,j,n} \frac{\partial f(\boldsymbol{x}; \boldsymbol{\theta}(0))}{\partial w_{i,j,n}^{(1)}} \cdot \frac{\partial f(\boldsymbol{x}'; \boldsymbol{\theta}(0))}{\partial w_{i,j,n}^{(1)}}}, 
    \quad
    K^{(2)}(\boldsymbol{x}, \boldsymbol{x}') = \displaystyle{\sum_{j,n} \frac{\partial f(\boldsymbol{x}; \boldsymbol{\theta}(0))}{\partial w_{j,1,n}^{(2)}} \cdot \frac{\partial f(\boldsymbol{x}'; \boldsymbol{\theta}(0))}{\partial w_{j,1,n}^{(2)}}}.
\end{equation}
This helps us understand the average behavior of the kernel at initialization.

\noindent
\textbf{Step I:} 
In this step, we consider the expectation of the second term,
\begin{equation}
\mathbb{E}[K^{(2)}(\boldsymbol{x}, \boldsymbol{x}')] = N \cdot \sum_{n=0}^k \mathbb{E} \left[ T_n(z_j(\boldsymbol{x})) \cdot T_n(z_j(\boldsymbol{x}')) \right],
\end{equation}
where $z_j(\boldsymbol{x}) = \tanh(h_j(\boldsymbol{x}))$ and $z_j(\boldsymbol{x}') = \tanh(h_j(\boldsymbol{x}'))$ are jointly distributed through the bivariate Gaussian pair $(h_j(\boldsymbol{x}), h_j(\boldsymbol{x}'))$ with zero mean and variances $\sigma_j^2(\boldsymbol{x})$ and $\sigma_j^2(\boldsymbol{x}')$, as defined previously in Eq.~\eqref{Eq:VarianceH}. The covariance between $h_j(\boldsymbol{x})$ and $h_j(\boldsymbol{x}')$ is given by,
\begin{equation}\label{Eq:CovH}
\mathrm{Cov}[h_j(\boldsymbol{x}), h_j(\boldsymbol{x}')] = \sum_{i=1}^d \sum_{n=0}^k T_n(\tanh(x_i)) \cdot T_n(\tanh(x'_i)) =: \rho_j(\boldsymbol{x},\boldsymbol{x}').
\end{equation}
Defining,
\begin{equation}
C_n(\boldsymbol{x}, \boldsymbol{x}') := \mathbb{E}\left[ T_n(\tanh(h)) \cdot T_n(\tanh(h')) \right],
\end{equation}
for $(h, h') \sim \mathcal{N}\left(0, \begin{bmatrix} \sigma^2(\boldsymbol{x}) & \rho(\boldsymbol{x},\boldsymbol{x}') \\ \rho(\boldsymbol{x},\boldsymbol{x}') & \sigma^2(\boldsymbol{x}') \end{bmatrix} \right)$, we obtain the compact expression,
\begin{equation}\label{Eq:StepI}
\mathbb{E}[K^{(2)}(\boldsymbol{x}, \boldsymbol{x}')] = N \cdot \sum_{n=0}^k C_n(\boldsymbol{x}, \boldsymbol{x}').
\end{equation}
Since Chebyshev polynomials are bounded on the interval $(-1, 1)$, and the $\tanh$ function maps Gaussian variables into this range, each term $C_n(\boldsymbol{x}, \boldsymbol{x}')$ remains finite.


\noindent
\textbf{Step II:} 
In the second step, we compute the expectation of the first-term kernel $\mathbb{E}[K^{(1)}(\boldsymbol{x}, \boldsymbol{x}')]$. 
Using Eq.~\eqref{Eq:firstdiff}, the first-term kernel can be written as,
\begin{equation}
K^{(1)}(\boldsymbol{x}, \boldsymbol{x}') = \sum_{i,j,n} A_{i,j,n}(\boldsymbol{x}) \cdot A_{i,j,n}(\boldsymbol{x}'),
\end{equation}
where,
\begin{equation}
A_{i,j,n}(\boldsymbol{x}) = T_n(\tilde{x}_i) \cdot \psi(\boldsymbol{x}) \cdot \sum_{m=0}^k w_{j,1,m}^{(2)} \cdot T_m'(\tanh(h_j(\boldsymbol{x}))),
\end{equation}
and $\psi(\boldsymbol{x}) = (1 - \tanh^2(h_j(\boldsymbol{x})))$.
Taking expectation with respect to the second-layer coefficients $w_{j,1,m}^{(2)} \sim \mathcal{N}(0,1)$, and noting that for fixed $h_j(\boldsymbol{x})$, the sum becomes a linear combination of independent Gaussian variables, we obtain a zero mean and the following variance,
\begin{equation}
\sum_{m=0}^{k} \left( T_m'(\tanh(h_j(\boldsymbol{x}))) \right)^2.
\end{equation}
This leads to the following expectation,
\begin{equation}
    \begin{array}{l}
      \mathbb{E}_{w^{(2)}}[A_{i,j,n}(\boldsymbol{x}) \cdot A_{i,j,n}(\boldsymbol{x}')] =  \\  T_n(\tilde{x}_i) \cdot T_n(\tilde{x}'_i) \cdot 
          \mathbb{E}_{h_j(\boldsymbol{x}), h_j(\boldsymbol{x}')} \Bigg[ \psi(\boldsymbol{x}) \cdot \psi(\boldsymbol{x}')\cdot \sum_{m=0}^{k} T_m'(\tanh(h_j(\boldsymbol{x}))) \cdot T_m'(\tanh(h_j(\boldsymbol{x}'))) \Bigg].
    \end{array}
\end{equation}
We denote the inner expectation as $D(\boldsymbol{x}, \boldsymbol{x}')$, defined by,
\begin{equation}
D(\boldsymbol{x}, \boldsymbol{x}') := \mathbb{E}_{h, h'}\left[
(1-\tanh^2(h)) \cdot (1-\tanh^2(h')) \cdot \psi(\boldsymbol{x}')\cdot \sum_{m=0}^{k} T_m'(\tanh(h)) \cdot T_m'(\tanh(h'))
\right],
\end{equation}
where $(h, h') \sim \mathcal{N}\left(0, \begin{bmatrix} \sigma^2(\boldsymbol{x}) & \rho(\boldsymbol{x}, \boldsymbol{x}') \\ \rho(\boldsymbol{x}, \boldsymbol{x}') & \sigma^2(\boldsymbol{x}') \end{bmatrix} \right)$. The variance and covariance terms are defined as (see Equations~\eqref{Eq:VarianceH} and~\eqref{Eq:CovH}),
\begin{equation}
\sigma^2(\boldsymbol{x}) := \mathrm{Var}[h_j(\boldsymbol{x})], \quad
\rho(\boldsymbol{x}, \boldsymbol{x}') := \mathrm{Cov}[h_j(\boldsymbol{x}), h_j(\boldsymbol{x}')].
\end{equation}
The derivatives $T_m'(\cdot)$ are evaluated elementwise inside the expectation, as they depend on the random variable $\tanh(h)$, a nonlinear transformation of the Gaussian variable $h$.
Since $h_j(\boldsymbol{x})$ are i.i.d. across neurons, the expectation becomes independent of the index $j$, yielding the simplified form,
\begin{equation}\label{Eq:StepII}
\mathbb{E}[K^{(1)}(\boldsymbol{x}, \boldsymbol{x}')] = N \cdot \sum_{i=1}^d \sum_{n=0}^k T_n(\tilde{x}_i) \cdot T_n(\tilde{x}'_i) \cdot D(\boldsymbol{x}, \boldsymbol{x}').
\end{equation}


Using Equations~\eqref{Eq:StepI} and \eqref{Eq:StepII}, we have, 
\begin{equation}
    \mathbb{E}[\boldsymbol{K}_{\text{ntk}}(\boldsymbol{x}, \boldsymbol{x}')] = N \cdot \left[
\sum_{n=0}^k C_n(\boldsymbol{x}, \boldsymbol{x}') + \sum_{i=1}^d \sum_{n=0}^k T_n(\tilde{x}_i) \cdot T_n(\tilde{x}'_i) \cdot D(\boldsymbol{x},\boldsymbol{x}')
\right],
\end{equation}
where $C_n(\boldsymbol{x},\boldsymbol{x}')$ is correlation of Chebyshev polynomials evaluated at $\tanh(h_j(\boldsymbol{x}))$ and $\tanh(h_j(\boldsymbol{x}'))$, and $D(\boldsymbol{x},\boldsymbol{x}')$ is expectation involving $\psi$ terms and Chebyshev polynomial derivatives.

