\section{Proof of Theorem \ref{Theorem:NTKConv}}\label{App.Proof2}

    Let $f(\boldsymbol{x}; \boldsymbol{\theta})$ be the output of a cKAN with parameters $\boldsymbol{\theta}$, and let $\boldsymbol{K}_{\text{ntk}}^{(\tau)}(\boldsymbol{x}, \boldsymbol{x}')$ denote the NTK between two inputs $\boldsymbol{x}$ and $\boldsymbol{x}'$ at training time $\tau$. By definition,
    \begin{equation}
        \boldsymbol{K}_{\text{ntk}}^{(\tau)}(\boldsymbol{x}, \boldsymbol{x}') = \left\langle \nabla_{\boldsymbol{\theta}} f(\boldsymbol{x}; \boldsymbol{\theta}(\tau)), \nabla_{\boldsymbol{\theta}} f(\boldsymbol{x}'; \boldsymbol{\theta}(\tau)) \right\rangle.
    \end{equation}
    We now differentiate this quantity with respect to the training time $\tau$ using the product rule,
    \begin{equation}
        \frac{d}{d\tau} \boldsymbol{K}_{\text{ntk}}^{(\tau)}(\boldsymbol{x}, \boldsymbol{x}') = \left\langle \nabla^2_{\boldsymbol{\theta}} f(\boldsymbol{x}; \boldsymbol{\theta}(\tau)) \cdot \dot{\boldsymbol{\theta}}(\tau), \nabla_{\boldsymbol{\theta}} f(\boldsymbol{x}'; \boldsymbol{\theta}(\tau)) \right\rangle + \left\langle \nabla_{\boldsymbol{\theta}} f(\boldsymbol{x}; \boldsymbol{\theta}(\tau)), \nabla^2_{\boldsymbol{\theta}} f(\boldsymbol{x}'; \boldsymbol{\theta}(\tau)) \cdot \dot{\boldsymbol{\theta}}(\tau) \right\rangle.
    \end{equation}
    Taking the absolute value and applying the Cauchy–Schwarz inequality and the uniform bounds $B_1, B_2$, we obtain the bound,
    \begin{equation}
        \left| \frac{d}{d\tau} \boldsymbol{K}_{\text{ntk}}^{(\tau)}(\boldsymbol{x}, \boldsymbol{x}') \right| \leq 2 B_1 B_2 \cdot \left\| \dot{\boldsymbol{\theta}}(\tau) \right\|.
    \end{equation}
    Integrating from $0$ to $\tau$, we get,
    \begin{equation}
        \left| \boldsymbol{K}_{\text{ntk}}^{(\tau)}(\boldsymbol{x}, \boldsymbol{x}') - \boldsymbol{K}_{\text{ntk}}^{(0)}(\boldsymbol{x}, \boldsymbol{x}') \right| \leq 2 B_1 B_2 \cdot \int_0^\tau \left\| \dot{\boldsymbol{\theta}}(s) \right\| ds = 2 B_1 B_2 \cdot \left\| \boldsymbol{\theta}(\tau) - \boldsymbol{\theta}(0) \right\|.
    \end{equation}
    Therefore, the matrix norm satisfies,
    \begin{equation}
        \left\| \boldsymbol{K}_{\text{ntk}}(\tau) - \boldsymbol{K}_{\text{ntk}}(0) \right\| \leq C \cdot \left\| \boldsymbol{\theta}(\tau) - \boldsymbol{\theta}(0) \right\|,
    \end{equation}
    for some constant $C = 2 B_1 B_2$. In the infinite-width limit, parameter drift satisfies,
    \begin{equation}
        \left\| \boldsymbol{\theta}(\tau) - \boldsymbol{\theta}(0) \right\| \to 0 \quad \text{as } N \to \infty,
    \end{equation}
    which implies,
    \begin{equation}
        \left\| \boldsymbol{K}_{\text{ntk}}(\tau) - \boldsymbol{K}_{\text{ntk}}(0) \right\| \to 0 \quad \text{as } N \to \infty.
    \end{equation}




