    \centering
    \fbox{\includegraphics[width=0.9\linewidth]{Figures/GT_GRN__.png}}
    \caption{Caption}
    \label{fig:GT_GRN}
\end{figure}


\subsubsection{Graph Positional Encodings}
NLP-based Transformers are supplied with Positional Encodings. At the heart of GT, graph positional encodings hold a special place which is important to encode node positions. From the available graph structure, we make use of Laplacian eigenvectors and use them as positional encoding (PE) information. This is helpful to encode distance-aware information, i.e., nearby nodes would have similar positional features and vice-versa. Eigenvectors are defined as the factorzation of the graph Laplacian matrix;

\begin{equation}
\Delta = I - D^{-\frac{1}{2}} A D^{-\frac{1}{2}} = U \Lambda U^{T}
\end{equation}

where $A$ is the adjacency matrix of $n \times n$ dimensions, $D$ is the degree matrix, $\Lambda$ is the eigenvalues and $U$ are the eigenvectors. We then use the $k$ smallest significant eigen-vectors of a node as its positional encoding, which is denoted by $\lambda_i$ for node $i$.

\subsubsection{Graph Transformer - Input Features Construction}
The input to the Graph Transformer (GT) layer is the graph structure \( \mathcal{G} \) and its associated features \( h \). The features \( h \) are constructed as a combination of gene expression embeddings (\( z \)), global gene embeddings (\( \xi \)), and graph positional embeddings (\( \lambda \)), which are derived from the graph \( \mathcal{G} \). 

\begin{itemize}

\item For gene expression embeddings, for example, a particular gene \( z_i \in \mathbb{R}^{d_n \times 1} \) is passed through a linear projection layer to embed these features into a \( d \)-dimensional space. 

\begin{equation}
    \hat{z}^0_i = S^0 z_i + s^0 
\end{equation}

where, \( S^0 \in \mathbb{R}^{d \times d_n} \) is a learnable weight matrix, \( s^0 \in \mathbb{R}^d \)is the learnable bias vector, and \( \hat{z}^0_i \in \mathbb{R}^d \).

\vspace{0.2cm}

\item For the global gene embeddings, say for \( \xi_i \in \mathbb{R}^{d_n \times 1} \) are also embedded into the \( d \)-dimensional space using another linear projection layer. The transformation is defined as:

\begin{equation}
    \hat{\xi}^0_i = T^0 \xi_i + t^0    
\end{equation}

where, \( T^0 \in \mathbb{R}^{d \times d_n} \) is a learnable weight matrix, \( t^0 \in \mathbb{R}^d \) is the learnable bias vector. 

\vspace{0.2cm}

\item The graph positional encodings are extracted from the input graph $\mathcal{G}$. For a particular gene's PE  \( \lambda_i \in \mathbb{R}^k \) is embedded into \( d \)-dimensional space using a linear projection layer which is given by:


\begin{equation}
    \lambda^0_i = U^0 \lambda_i + u^0    
\end{equation}



where, \( U^0 \in \mathbb{R}^{d \times k} \) is a learnable weight matrix, \( u^0 \in \mathbb{R}^d \) is a learnable bias vector. 

\end{itemize}

Finally, the gene expression embeddings $\hat{z}^0$, global gene embeddings $\hat{\xi}^0$ and graph positional embeddings $\lambda$ are concatenated to make up the final to the node features \( h \):


\begin{equation}
    h =  \hat{z}^0 + \hat{\xi}^0 + \lambda^0 
\end{equation}

The final $h$ is injected into the GT layer along with the adjacency matrix $\mathcal{A}$ of $\mathcal{G}$.


\subsubsection{Graph Transformer Layer} The node update in the GT at layer $l$ is defined as follows: 

\begin{equation}
\hat{h}_{i}^{\ell+1} = O_h^{\ell} \, \bigg\|_{k=1}^{H} \left( \sum_{j \in \mathcal{N}(i)} w_{ij}^{k,\ell} V^{k,\ell} h_{j}^{\ell} \right)
\end{equation}

\begin{equation}
\text{where,} \thickspace  w_{ij}^{k,\ell} = \text{softmax}_j \left( \frac{Q^{k,\ell}h_{i}^{\ell} \cdot K^{k,\ell} h_{j}^{\ell}}{\sqrt{d_k}} \right),
\end{equation}

and $Q^{k,l}$, $K^{k,l}$, $V^{k,l} \in \mathbb{R}^{d_k \times d}$, $O^{l}_h \in \mathbb{d \times d}$, $k=1 \thickspace \text{to} \thickspace H$ denotes number of attention heads, and $\bigg\|$ denotes the contatenation of the number of heads. The attention outputs $\hat{h}_i^{l+1}$ are then passed to a Feed Forward Network (FFN) preceded and succeeded by residual connections and normalization layers as:


\begin{equation}
    \hat{\hat{h}}_{i}^{\ell+1} = \text{Norm} \left( h_{i}^{\ell} + \hat{h}_{i}^{\ell+1} \right)
\end{equation}


\begin{equation}
    \hat{\hat{\hat{h}}}_{i}^{\ell+1} = W_{2}^{\ell} \, \text{ReLU} \left( W_{1}^{\ell} \hat{\hat{h}}_{i}^{\ell+1} \right)
\end{equation}

% ........................ l  and el

\begin{equation}
    h_{i}^{\ell+1} = \text{Norm} \left( \hat{\hat{h}}_{i}^{\ell} + \hat{\hat{\hat{h}}}_{i}^{\ell+1} \right)
\end{equation}

where $W^l_1 \in \mathbb{R}^{2d \times d}$, $W_2^l \in \mathbb{R}^{d \times 2d}$, and $\hat{\hat{h}}_i^{l+1}$, $\hat{\hat{\hat{h}}}_i^{l+1}$ are the intermediate representations. Norm could be either Layer-Norm\cite{ba2016layer} or BatchNorm\cite{ioffe2015batch}.


\subsubsection{Link Prediction with learned representations}
The final module is designed to predict edges between nodes using the learned node representations \( h^{\ell+1} \) obtained from the GT layer. The module takes as input the embeddings \( h^{\ell+1} \in \mathbb{R}^{N \times d} \), where \( N \) is the number of nodes and \( d \) is the embedding dimension, along with an edge index representing node pairs. For each edge \( (i, j) \), the embeddings of the source node \( h^{\ell+1}_i \) and the destination node \( h^{\ell+1}_j \) are extracted and concatenated to form a feature vector. This vector is passed through a decoder network consisting of a multi-layer perceptron (MLP) with a hidden layer, ReLU activation, and an output layer, which reduces the concatenated vector to a scalar. The scalar represents the predicted likelihood of an edge between the nodes \( i \) and \( j \). By utilizing the updated node embeddings \( h^{\ell+1} \), this module effectively learns to identify and score potential edges in the graph.



\subsection{Experimental Setup}
The performance of \emph{GT-GRN} is evaluated on Linux based NVIDIA RTX A3000 GPU as the computing machine. The deep learning libraries used here are pytorch\footnote{\url{https://pytorch.org/}}, dgl \footnote{\url{https://www.dgl.ai/}}, scikit-learn\footnote{\url{https://scikit-learn.org/stable/}}. 
\subsection{Datasets}
