\section{Proof of Theorem \ref{length.thm}}
The proof of Theorem \ref{length.thm} is given in this section. 

\begin{proof}
From Theorem \ref{th3}, the lengths are expressed as 
\begin{align*}
    L_{i,TD}&=\frac{1}{1+a_iD_i/2}\{g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^D)\},\\
    L_{i,TEB}&=\frac{1}{1+a_iD_i/2}\{g^{-1}(\hat I_{i,U}^{EB})-g^{-1}(\hat I_{i,L}^{EB})\},
\end{align*}
where $\hat I_{i,U}$ and $\hat I_{i,L}$ is the upper and lower limits of $\hat I_{i}$, respectively. 

\noindent Then it follows that
\begin{align}
    L_{i,TD}-L_{i,TEB}&=\frac{1}{1+a_iD_i/2}[g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^D)-\{g^{-1}(\hat I_{i,U}^{EB})-g^{-1}(\hat I_{i,L}^{EB})\}],\notag\\
    &=(1+O_p(n_i^{-1}))[g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^D)-\{g^{-1}(\hat I_{i,U}^{EB})-g^{-1}(\hat I_{i,L}^{EB})\}].\label{eq1250401}
\end{align}

\noindent We evaluated $g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^D)$ at first. 
\begin{align}
    g^{-1}(\hat I_{i,U}^D)&-g^{-1}(\hat I_{i,L}^D)=g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^{EB})-\{g^{-1}(\hat I_{i,L}^D)-g^{-1}(\hat I_{i,L}^{EB})\},\notag\\
    =&(\hat I_{i,U}^D-\hat I_{i,L}^D)\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}+\frac{1}{2}\{(\hat I_{i,U}^D-\hat I_{i,L}^{EB})^2-(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^2\}\{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\notag\\
     &+\frac{1}{6}\{(\hat I_{i,U}^D-\hat I_{i,L}^{EB})^3-(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^3\}\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^*}\notag\\
     &+\frac{1}{6}(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^3[\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^*}-\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^{**}}],\label{eq241018.1}
\end{align}
where $x^*$ and $x^{**}$ lies between $\hat I_{i,U}^{D}$ and $\hat I_{i,L}^{EB}$, $\hat I_{i,L}^{D}$ and $\hat I_{i,L}^{EB}$ respectively. 

\begin{align*}
    (\hat I_{i,U}^D-\hat I_{i,L}^{EB})^2-&(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^2=(\hat I_{i,U}^D-\hat I_{i,L}^{D})^2+2(\hat I_{i,U}^D-\hat I_{i,L}^{D})(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB}),\\
    =&4z_{\alpha/2}^2D_{i}+4z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}-z_{\alpha/2}(\sqrt{D_i}-\sqrt{g_{1i}(\hat A)})\},\\
    =&4z_{\alpha/2}^2D_{i}+4z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}+O_p(n_i^{-2}).
\end{align*}

\begin{align*}
    (\hat I_{i,U}^D-\hat I_{i,L}^{EB})^3-&(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^3=(\hat I_{i,U}^D-\hat I_{i,L}^{D})^3+3(\hat I_{i,U}^D-\hat I_{i,L}^{D})^2(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})\\
    &+3(\hat I_{i,U}^D-\hat I_{i,L}^{D})(\hat I_{i,L}^{D}-\hat I_{i,L}^{EB})^2,\\
    =&8z_{\alpha/2}^3D_{i}^{3/2}+12z_{\alpha/2}^2D_{i}\{g(y_i)-\hat \theta_i^{EB}\}+6z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}^2+O_p(n_i^{-2})
\end{align*}
In the above calculation, we used $\sqrt D_i-\sqrt{g_{1i}(\hat A)}=O_p(n_i^{-3/2})$ and $\hat I_{i,L}^{D}-\hat I_{i,L}^{EB}=g(y_i)-\hat \theta_i^{EB}+O_p(n_i^{-3/2})=O_p(n_i^{-1})$. 


\begin{align*}
    \eqref{eq241018.1}=&2z_{\alpha/2}\sqrt{D_{i}}\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}
    +[2z_{\alpha/2}^2D_{i}+2z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}]
    \{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\\
    &+\left\{\frac{4}{3}z_{\alpha/2}^3D_{i}^{3/2}+2z_{\alpha/2}^2D_{i}\{g(y_i)-\hat \theta_i^{EB}\}+z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}^2\right\}\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^*}\\
    &+O_p(n_i^{-2}),\\
    =&2z_{\alpha/2}\sqrt{D_{i}}\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}
    +2[z_{\alpha/2}^2D_{i}+z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}
    \{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\\
    &+\frac{4}{3}z_{\alpha/2}^3D_{i}^{3/2}\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^*}+O_p(n_i^{-2}).
\end{align*}
Note that $g(y_i)-\hat \theta_i^{EB}=O_p(n_i^{-1}).$

Next, using a similar way, it follows that 
\begin{align}
    g^{-1}(\hat I_{i,U}^{EB})&-g^{-1}(\hat I_{i,L}^{EB})
    =(\hat I_{i,U}^{EB}-\hat I_{i,L}^{EB})\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}+\frac{1}{2}(\hat I_{i,U}^{EB}-\hat I_{i,L}^{EB})^2\{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\notag\\
    &+\frac{1}{6}(\hat I_{i,U}^{EB}-\hat I_{i,L}^{EB})^3\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^{***}},\notag\\
    =&2z_{\alpha/2}\sqrt{g_{1i}(\hat A)}\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}
    +2z_{\alpha/2}^2g_{1i}(\hat A)\{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\notag\\
    &+\frac{4}{3}z_{\alpha/2}^3g_{1i}(\hat A)^{3/2}\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^{***}},    \label{eq241018.2}
\end{align}
where $x^{***}$ lies between $\hat I_{i,U}^{EB}$ and $\hat I_{i,L}^{EB}$. 

Hence, we obtain using \eqref{eq1250401}-\eqref{eq241018.2},
\begin{align*}
L_{i,TD}-L_{i,TEB}=&(1+O_p(n_i^{-1}))[g^{-1}(\hat I_{i,U}^D)-g^{-1}(\hat I_{i,L}^D)-\{g^{-1}(\hat I_{i,U}^{EB})-g^{-1}(\hat I_{i,L}^{EB})\}],\\
=&2z_{\alpha/2}(\sqrt{D_{i}}-\sqrt{g_{1i}(\hat A)})\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat I_{i,L}^{EB}}\\
    &+2z_{\alpha/2}^2\{D_{i}-g_{1i}(\hat A)\}\{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\\
    &+2z_{\alpha/2}\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}
    \{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat I_{i,L}^{EB}}\\
    &+\frac{4}{3}z_{\alpha/2}^3\{D_{i}^{3/2}-g_{1i}(\hat A)^{3/2})\}\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^*}\\
    &-\frac{4}{3}z_{\alpha/2}^3g_{1i}(\hat A)^{3/2}\left\{\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^{***}}-\{g^{-1}(x)\}^{\prime \prime \prime}\Big |_{x=x^{*}}
    \right\}+O_p(n_i^{-2}),\\
=&2z_{\alpha/2}\Big[(\sqrt{D_{i}}-\sqrt{g_{1i}(\hat A)})\{g^{-1}(x)\}^{\prime}\Big |_{x=\hat \theta_i^{EB}}\\
    &+\sqrt{D_{i}}\{g(y_i)-\hat \theta_i^{EB}\}
    \{g^{-1}(x)\}^{\prime \prime}\Big |_{x=\hat \theta_i^{EB}}\Big]+O_p(n_i^{-2}),
 \end{align*}
The last equation obtained by noting that $x^*-x^{***}=O_p(n_i^{-1})$ as follows from their definitions. The result that $\hat I_{i,L}^{EB}=\hat \theta_i^{EB}+O_p(n_i^{-1/2})$ is also used for the last equation. 

\end{proof}

