\title{Geo-Disasters: geocoding climate-related events in the international disaster database EM-DAT}

\author[1,*]{Khalil Teber}
\author[3]{Mélanie Weynants}
\author[3]{Fabian Gans}
\author[1,2]{Miguel D. Mahecha}
\affil[1]{Institute for Earth System Science and Remote Sensing, Leipzig University, Leipzig, 04103, Germany}
