\subsection{An Actor-Critic Algorithm}

 It is well known that in order to solve \eqref{prob}, %for each $\iota =1, \cdots, m$, 
 we need to use the famous Bellman Dynamical Programming Principle equation

 \beq{DDP}
Q_{p+1}(s, \iota, a) = \ee\bigg[R_{p}  + \gamma \max_{\pi} Q_{p}(s',\iota', a')
 \bigg{|} s'=s,\iota'=\iota, a'=a \bigg], \nonumber \\
  p=0, 1, \cdots.
\eeq

 Taking into account the action of Markov Chain $(\al_k)_k$,
\[
Q_{p}(s_{p+1}, \iota, a_{p+1})=\sum_{j\in {\cal M}}P_{\iota, j} Q_{p}(H(s_{p-1}, a_{p-1}, \iota), j, a_{p+1}),
\]
recall the stock prices dynamics are captured by an operator $H$, the Bellman Dynamical Programming Principle equation (Equation \eqref{DDP}) becomes
\beq{DDP1}
Q_{p+1}(s, \iota, a) = \ee\bigg[R_{p}  + \gamma \max_{\pi} \sum_{j\in {\cal M}}P_{ \iota, j} Q_{p}(s', j, a')
 \bigg{|} a'=a, s'=H(s,a,\iota)\bigg], \nonumber \\
 \qquad p=0, 1, \cdots, \iota =1,2,\cdots, m.
\eeq


