For each  $\iota\in \{1, \cdots, m\}$, we define the average reward as 
\beq{averageReward}
J(\pi) = \ee\bigg[\sum_{k=1}^\infty\gamma^{k-1}R_k \bigg{|} s_0, \alpha_0,  \pi \bigg]
\eeq
and  we have
\beq{QfunctionII}
Q^{\pi}(s, \iota, a) = \ee\bigg[\sum_{k=1}^\infty\gamma^{k-1}R_k 
\bigg{|} s_0=s, \alpha_0 = \iota, a_0 = a, \pi \bigg].
\eeq

Moreover we define the discounted states visited starting in state $s_0$ and following the policy $\pi$ as following
\begin{equation}\label{strating}
d^{\pi}(s, \iota)= \sum_{k=0}^\infty \gamma^k {\Bbb P}(s_k = s, \alpha_k =\iota| s_0, \alpha_0,  \pi).
\end{equation}  


