\begin{equation*}
 e^\pi(\omega)= \sum_{s \in {\cal S}, \iota\in {\cal M}}d^\pi(s, \iota)\sum_{a \in{\cal A}}\pi(s, \iota, a)\abs{ Q^\pi(s,\iota, a)- \hat{Q}^\pi_\omega(s, \iota, a) } ^2
