%\beq{error}
%\qquad e^\pi(\omega)&=& \sum_{\iota =1}^{m}\sum_{s \in {\cal S}}d^\pi(s)\sum_{a \in{\cal A}}\pi(s,a, \theta)\lVert \bm{Q}^\pi(s,a)  \\
%&&\hspace{0.5 in} - \bm{\hat{Q}}^\pi_\omega(s,a)\rVert^2, \nonumber
