which means that we should at least have
\beq{condition}
\nabla_\omega e^\pi(\omega) &=&  2 \sum_{s \in {\cal S}, \iota\in {\cal M}} d^\pi(s, \iota)\sum_{a\in {\cal A}}\pi(s, \iota, a)\bigg( Q^\pi(s, \iota, a)  \nonumber\\
&&\hspace{0.5 in} - \hat{Q}^\pi_\omega(s, \iota, a)\bigg)\nabla_\omega \hat{Q}^\pi_\omega(s, \iota, a) \\
&=&0. \nonumber
\eeq

Sutton et al. \cite{Sutton2000} showed any if each coordinate of an approximator $\bm{\hat{Q}}^\pi_\omega(s,a)$ satisfies \eqref{condition} and is such that
\beq{4Eq} 
 \disp \nabla_\omega \hat{Q}^\pi_\omega(s, \iota, a)= \frac{\nabla_\theta\pi(s, \iota,  a)}{\pi(s, \iota, a)}, \forall \iota\in{\cal M},
\eeq then
\beq{functionGradient}
\qquad \qquad \nabla_\theta J(\pi) =\sum_{s \in {\cal S}, \iota\in {\cal M}}d^\pi(s, \iota)\sum_{a\in {\cal A}}\nabla_\theta\pi(s, a, \iota)\hat{Q}^\pi_\omega(s, a, \iota), \forall \iota\in{\cal M}.
\eeq
Moreover, we also assume that our policy function $\pi(s,\iota, a)$ is in  the form of a Gibbs (Boltzmann) distribution
\beq{policyform}
\quad \quad \quad\disp \pi(s, \iota, a,  \theta) = \frac{e^{\theta^T\phi_{s\iota a}}}{\sum_{a'}e^{\theta^T\phi_{s\iota a'}}}, \quad \forall s \in {\cal S},\,\,\, \forall a \in {\cal A}, \ \ \forall \iota \in {\cal M}
\eeq
where $\phi_{sa\iota}$ is a feature vector characterizing the state-action-jump triplet for each $s$, $a$ and $\iota$. So using \eqref{4Eq} and \eqref{policyform} we have
\beq{NewEq}
\nabla_\omega\hat{Q}^\pi_\omega(s,\iota, a)= \phi_{s\iota a}-\sum_{b\in{\cal A}} \pi(s, \iota, b, \theta)\phi_{s\iota b}, \ \forall \iota \in {\cal M}.
\eeq
 Since it is preferable for  $\hat{Q}^\pi_\omega(s, \iota, a)$ to be a linear function of $\omega$ in order to satisfy all convergence conditions, thus this implies that 
 \beq{MousEq}
\qquad \qquad \hat{Q}^\pi_\omega(s, \iota, a) = \omega^T\bigg(  \phi_{s\iota a}-\sum_{b\in{\cal A}} \pi(s, \iota, b,  \theta)\phi_{s\iota b} \bigg), \ \forall \iota \in {\cal M} .
 \eeq 
\begin{theorem}
Given any initial parameter vector $\theta_0$,  the sequence of average reward $(J(\pi_k))_{k \in \mathbb{N}}$, with $\pi_k=\pi(\cdot, \cdot, \cdot, \theta_k)$ and 
\beq{wsed}
\omega_k \disp= \omega \quad \hbox{ such that }  \quad \nabla_\omega e^{\pi_k}(\omega) = 0
\eeq
and
\bea
 \theta_{k+1}&\disp  = \theta_k + \frac{1}{k}\sum_{s\in {\cal S}, \iota \in {\cal M}}d^{\pi_k }(s, \iota)\sum_{a\in {\cal A}}\nabla_\theta\pi_k(s,\iota, a) \hat{Q}^{\pi_k}(s, \iota, a)
\eea is such that 
\beq{lim}
\lim_{k\to \infty} \nabla_{\theta}J(\pi_k) = 0.
\eeq   
\end{theorem}


