\section{The Minimal Shortfall Execution}
\begin{comment}
\todo[inline]{Our goal is to minimize }
\todo[inline]{Our goal is to minimize the expected shortfall
\[
\frac{1}{n}\sum a_ie_i\leq \frac{1}{2n}\sum a_i^2+e_i^2
\]
}
\end{comment}
Minimum shortfall methods are usually applied to liquidate orders. In this section, we propose a liquidation strategy that addresses the issue for a basket of stocks.
%that factors in the fact that the market may have multiple regimes before the execution is completed. 
The main goal of liquidating orders is to minimize the shortfall.

 Consider a basket of stocks $(S_{1,k})_k, (S_{2,k})_k, ..., (S_{n,k})_k$  defined in \eqref{dynamics}. For each stock $(S_{i,k})_k, i=1,..., n$, let $\bar{s}_i$ represents the arrival price for the $i$-th stock, i.e., the stock price value when the execution order is given. The  expected shortfall of the $i$-th stock at till the $k$-th trading time is defined as follows
 \beq{shortfalli}
F_{i,k} = \sum_{j=1}^k  \mathbb{E}\bigg[a_{i,j}(S_{i,j}  -  \bar{s}_i)\bigg] 
\eeq
where $\mathbb{E}$ represents the probability expectation,
and the overall expected shortfall for the basket of stocks after the $k$-th trading time  is 
\beq{shortfall}
F_k = \sum_{i=1}^n F_{i,k}.
\eeq
Our goal is to devise a trading algorithm that will over a finite horizon minimize the process $(F_k)_k$. We will search for a strategy such that the stock $S_i$ is sold as close as possible to the arrival price $\bar{s}_{i}$, $i=1, \ldots, n$. Let $x_{i,k}:= S_{i,k}-\bar{s}_i$ be the shortfall tracking error for the $i$-th stock at the $k$-th trading time.  In other words, our goal is to drive the error $x_{i,k}$ as close as possible to zero as we are selling for each $i=1, \ldots, n$.
Since we assume the stock prices dynamics are captured by the operator $H$, given by\eqref{eq: model}, denote the shortfall error vector by $x_k=(x_{1,k}, \ldots, x_{n,k})$ and the arrival price vector by $\bar{s}=(\bar{s}_1, \ldots, \bar{s}_n)$, it is easy to see that $x_{k+1}=H(x_k,a_k, \xi_k)$ satisfying

\beq{error dynamics} \label{eq: error model}
\qquad \left\{\begin{array}{ll}
\disp x_{i,k+1}&=x_{i,k} + \tau \big(f_i( a_{i,k})+ \mu_i \big)x_{i, k} +  \sqrt{\tau} \sum_{i,j=1}^n \sigma_{ij} \xi_{j,k}x_{i,k}\\
&+\bar{s}_i\big(f_i( a_{i,k})+ \mu_i \big)+\bar{s}_i\sqrt{\tau} \sum_{i,j=1}^n \sigma_{ij} \xi_{j,k},\\
x_{i,0} &= s_i-\bar{s}_i, \quad i= 1,..., n; \quad  k\geq 0.
 \end{array}\right.
\eeq

Then the expected shortfall can be written as a function of the tracking error:

 \beq{shortfalli_trackingerror}
F_{i,k} = \sum_{j=1}^k  \mathbb{E}\bigg[a_{i,j}x_{i,k} \bigg], \text{ and } \ F_k = \sum_{i=1}^n F_{i,k}. 
\eeq

To achieve this goal, we propose a new computational method, i.e.,  a reinforcement learning-based linear quadratic regulator approach. We will first define the $Q$-function for the minimal shortfall execution. 

\begin{comment}
 \beq{shortfalli}
F_{i,k} = \sum_{j=1}^k  \bigg[a_{i,j}^2\bigg( S_{i,j}  -  \bar{s}_i\bigg)^2\bigg] =  \sum_{j=1}^k a_{i,j}^2x_{i,j}^2,
\eeq
and the overall shortfall for the basket of stocks after the $k$-th trading time  is 
\beq{shortfall}
F_k = \sum_{i=1}^n F_{i,k}
\eeq   
\end{comment}




%In order to achieve that goal, we introduce a parametrized approximate value function $Q(a,s;\theta_i)$ using deep convolutional neural network in which $\theta_i$ are the parameters in other terms the weights  of the $Q$-network at iteration $i$.





\begin{defn}\label{q-function1}
 Given a policy $\pi$ with initial action $a_0=a$ and given an initial tracking error $x_0 =x$ with  $x= s-\bar{s}$ %$S_0 = s$,
 we define the $Q$-functions of the policy $\pi$ as follows
 \beq{value_function_iterative}
 Q^\pi_p(x, a)  \disp = \ee\bigg[ \sum_{k=1}^p \sum_{i=1}^n  \gamma^{k-1}F_{i,k}
  \bigg{|} e_0=x, a_0=a; \pi\bigg],
 \eeq
 \beq{value-function}
 Q^\pi(x, a)\disp = \ee\bigg[ \sum_{k=1}^\infty \sum_{i=1}^n  \gamma^{k-1}F_{i,k} 
   \bigg{|} e_0=x, a_0=a; \pi\bigg].
 \eeq 
 One can obviously see that $\disp \lim_{p\to \infty } Q^\pi_p(x, a)  = Q^\pi(x, a) $.\\
The state-action value functions of our control problem are defined as follows
 \beq{valuefunctioniterative1}
Q_p(x,a) \disp= \min_{\pi}Q^\pi_p(x,a)
\eeq
 and
\beq{valuefunction1}
Q(x,a) \disp= \min_{\pi}Q^\pi(x,a).
\eeq
We have $\disp \lim_{p\to \infty } Q_p(x, a)  = Q(x,  a) $.
\end{defn}

Denote the state space of $(x_k)_k$ by $\mathcal{S}$. Our main goal is, for each $x\in\cal S$,   to find the optimal policy, say $\pi^*$, such that 
\beq{prob1}
Q(x, a) \disp= \min_{\pi}Q^\pi(x, a) = Q^{\pi^*}(x, a).
\eeq


\subsection{A Reinforcement Learning Algorithm}

It is easy to see that in order to solve \eqref{prob1}, %for each $\iota =1, \cdots, m$, 
 we need to use the famous Bellman Dynamical Programming Principle equation

 \beq{DDPshortfall}
Q_{p+1}(x, a) = \ee\bigg[F_{p}  + \gamma \min_{\pi} Q_{p}(x', a')
 \bigg{|} x'=x, a'=a \bigg], \nonumber \\
  p=0, 1, \cdots.
\eeq
Theoretically, the iterative value function $Q_{p+1}(x, a) $ converges to the value function $Q(x, a).$ But this approach usually leads to the curse of dimensionality and many other stability issues. In order to address these issues, %In order to circumvent these issues
we will use parametric function approximations. 
In this methodology we will simultaneously approximate the optimal policy and the value function.  Each parametric function approximator is a neural network. Therefore, we will have two neural networks. The weights of our neural network will be the parameters of our function approximators. 

Denoted by $\cal{A}$ the state space of actions $(a_k)_k$, we call it the action space. It is clear that the triplet$(x_k, a_k, R_k)_k$ constitutes a Markov Decision process with transition probabilities $P(x, a,  x'):={\Bbb P}(x_{k+1}=x', |x_k=x, a_k=a)$, for any $x,x'$  in state space ${\cal S}$ and  $a$ in action space ${\cal A}$. 
We define our policy function as follows $\pi(x, a, \theta):= {\Bbb P}(a_k = a|x_k = x,\theta)$, $\forall x\in\cal S$, $a\in\cal A$, where $\theta$ is the vector of parameters of the neural network that will approximate the policy. For simplicity, we write just $\pi(x, a )$ for $\pi(x, a,  \theta)$.
To solve this problem we make the following assumptions:
\begin{itemize}
\item {\bf (A1)}: We assume that under any policy $\pi=(a_k)_k$ our Markov Decision Process is irreducible and aperiodic.

\item {\bf (A2)}: We assume that our policy function $\pi(x, a, \theta)$ is differentiable with respect to $\theta$.
\end{itemize}  


We define the average reward as 
\beq{averageReward-shortfall}
\rho(\pi) = \ee\bigg[\sum_{k=1}^\infty\gamma^{k-1}F_k \bigg{|} x_0,  \pi \bigg]
\eeq
and  we have
\beq{QfunctionII-shortfall}
Q^{\pi}(x, a) = \ee\bigg[\sum_{k=1}^\infty\gamma^{k-1}F_k 
\bigg{|} x_0=x,a_0 = a, \pi \bigg].
\eeq

Moreover we define the discounted states visited starting in state $s_0$ and following the policy $\pi$ as following
\begin{equation}\label{strating}
d^{\pi}(x)= \sum_{k=0}^\infty \gamma^k {\Bbb P}(x_k = x| x_0,  \pi).
\end{equation}  

It  is well known from the literature Sutton et al. \cite{Sutton2000}, and Marbach and Tsitsiklis \cite{Marbach2001} that,  we have 
\beq{Policy-shortfall}
\qquad\,\,\,\,\nabla_{\theta} \rho(\pi)
= \sum_{x\in\cal S}d^\pi(x) \sum_a \nabla_{\theta} \pi(x, a, \theta)Q^\pi(x, a).
\eeq


It is clear that anytime the policy $\pi$ is updated this also affects the state-action value function $Q^\pi(x, a)$. Thus given that we will approximate the policy with a parametric function (neural network), we will also approximate the state-action value function with another parametric function approximator denoted $\hat{Q}_\omega^\pi(x, a)$ where $\omega$ represents the vector of weights of the second neural network. One of the necessary conditions for the convergence of the approximation of $Q^\pi$ is that its approximator minimizes the mean-squared error:
\beq{error}
\qquad e^\pi(\omega)&=& \sum_{x \in {\cal S}}d^\pi(x)\sum_{a {\cal A}}\pi(x,a)\bigg( Q^\pi(x,a)  \\
&&\hspace{0.5 in} - \hat{Q}^\pi_\omega(x,a)\bigg)^2, \nonumber
\eeq
which means that we should at least have
\beq{condition}
\nabla_\omega e^\pi(\omega) &=&  2 \sum_{x \in {\cal S}}d^\pi(x)\sum_{a {\cal A}}\pi(x,a)\bigg( Q^\pi(x,a)  \nonumber\\
&&\hspace{0.5 in} - \hat{Q}^\pi_\omega(x,a)\bigg)\nabla_\omega \hat{Q}^\pi_\omega(x,a) \\
&=&0. \nonumber
\eeq
Sutton et al. \cite{Sutton2000} showed any if an approximator $\hat{Q}^\pi_\omega(x,a)$ satisfies \ref{condition} and is such that
\beq{4Eq} 
 \disp \nabla_\omega \hat{Q}^\pi_\omega(x,a)= \frac{\nabla_\theta\pi(x,a)}{\pi(x,a)}
\eeq then
\beq{functionGradient}
\qquad \qquad \nabla_\theta \rho^\pi(\theta) =\sum_{x \in {\cal S}}d^\pi(x)\sum_{a\in {\cal A}}\nabla_\theta\pi(x,a)\hat{Q}^\pi_\omega(x,a).
\eeq
Moreover, we also assume that our policy function $\pi(x,a,\theta)$ is in  the form of a Gibbs (Boltzmann) distribution
\beq{policyform}
\quad \quad \quad\disp \pi(x,a, \theta) = \frac{e^{\theta^T\phi_{xa}}}{\sum_{a'}e^{\theta^T\phi_{xa'}}}, \quad \forall x \in {\cal S},\,\,\, \forall a \in {\cal A},
\eeq
where $\phi_{xa}$ is a feature vector characterizing the state-action pair for each $x$ and $a$. So using \ref{4Eq} and \ref{policyform} we have
\beq{NewEq}
\nabla_\omega\hat{Q}^\pi_\omega(x,a)= \phi_{xa}-\sum_{b\in{\cal A}} \pi(x,b)\phi_{xb}.
\eeq
 Since it is preferable for  $\hat{Q}^\pi_\omega(x, a)$ to be a linear function of $\omega$ in order to satisfy all convergence conditions, thus this implies that 
 \beq{MousEq}
\qquad \qquad \hat{Q}^\pi_\omega(x,a) = \omega^T\bigg(  \phi_{xa}-\sum_{b\in{\cal A}} \pi(x,b)\phi_{xb} \bigg).
 \eeq 

\begin{theorem}
Given any initial parameter vector $\theta_0$,  the sequence of average reward $(\rho(\pi_k))_{k \in \mathbb{N}}$, with $\pi_k=\pi(\cdot, \cdot, \theta_k)$ and 
\beq{wsed}
\omega_k \disp= \omega \quad \hbox{ such that }  \quad \nabla_\omega e^{\pi_k}(\omega) = 0
\eeq
and
\bea
 \theta_{k+1}&\disp  = \theta_k + \frac{1}{k}\sum_{x\in {\cal S}}d^{\pi_k }(x)\sum_{a\in {\cal A}}\nabla_\theta\pi_k(x, a) \hat{Q}^{\pi_k}(x, a)
\eea is such that 
\beq{lim}
\lim_{k\to \infty} \nabla_{\theta}\rho(\pi_k) = 0.
\eeq   
\end{theorem}

\paragraph{Proof.}
Given the total number of shares that we want to liquidate is finite $\sum_{i=1}^n N_i<\infty$, then the states that our MDP will visit and the actions it will take until we complete our liquidation are both finite. So the sets ${\cal E}$ and ${\cal A}$ are finite sets. Using \eqref{policyform} it is easy to see that when $a$ and $x$ are fixed, the second partial derivative of the policy function $\pi(x, a,  \theta)$ with respect to theta is bounded. In fact, we have 
\beq{derivatives}
\abs{\frac{\partial^2 \pi(x, a,  \theta)}{\partial \theta_i\partial \theta_j}}< B_{x, a} \qquad \forall i, \, j.
\eeq
Moreover, given that the state spaces ${\cal S}$, and the action space ${\cal A}$  are finite sets then there exists $B<\infty$  such that
\beq{maxDeriv}
\max_{\theta, x, 
a, i, j}\abs{\frac{\partial^2 \pi(x,a, \theta)}{\partial \theta_i\partial \theta_j}}< B<\infty.
\eeq
Moreover our shortfall $ F=(F_k)$ is uniformly bounded because after a while the trader will have finished the liquidation and exited the market, so there exits $K>0$ such that for any $n >K$, $F_n=0$. It is clear that the sampling step-size sequence $\beta_k = \frac{1}{k}$ satisfies the condition
\bea
&\disp \sum_{k}\alpha_k = \sum_{k}\frac{1}{k} = \infty \\
 &$ and $ \lim_{k\to \infty} \beta_k = \lim_{k \to \infty} \frac{1}{k}=0.
\eea
Consequently using Theorem 3 from  Sutton et al. \cite{Sutton2000} we have have the convergence of the sequence of average reward in the sense that 
\bea
\disp \lim_{k \to \infty} \nabla_\theta \rho(\pi_k) = 0.
\eea
\endproof.
\section{Implementation}

The training environment of our reinforcement learning schema is our model \ref{dynamics}. In this model we assume the stocks we want to liquidate are highly correlated and that our trading actions will incur a linear market impact.  We store experimental data $\epsilon_k = (x_k, a_k, F_k, x_{k+1})$ at the $k$-th step in a   data set $ D_k = \{\epsilon_1, \epsilon_2,\ldots, \epsilon_k\}$. During learning, we estimate Q-function by drawing uniformly at random from the pool of stored data. We use the following algorithm.
\begin{algorithm}
%\caption{An algorithm with caption}\label{algcap}
\begin{algorithmic}\\
\State Initialize replay memory $D$ to capacity $N_D$.
\State Initialize the action-value function estimate $\hat{Q}_\omega$  with random weights $\omega$.  
\State Initialize the policy function $\pi(\cdot, \cdot, \theta)$  with random weights $\theta$
\State Initialize the target network  $\hat{Q}'_{\omega'}$ and $\pi'(\cdot, \cdot, \theta')$ with weights $\omega' \gets \omega$ and $\theta' \gets \theta$.
\For{ episode=1 to $M$ }\\
    Received the first state $e_1$
     \For{k=1 to K}
    \State  With probability $\varepsilon$ select a random action $a_k$ otherwise
      set  $a_k = \arg\max_{a \in {\cal A}}\hat{Q}_\omega(x_k, a, \omega)$
     \State  Execute action $a_k$ and observed reward $R_k$, then compute the next state $x_{k+1} = H(x_k, a_k,\xi_k)$.
	\State Store transition $\epsilon_k=(x_k, a_k, F_k, x_{k+1})$ in $D$.
	\State Sample a random mini-batch of $N_D$ $(x_i,a_i, F_i, x_{i+1})$  transitions from $D$.
	\State Set $y_i = F_i +\gamma \hat{Q}_{\omega'}'(x_{i+1}, a_{i+1})$.
	\State Update  $\omega_{k+1}$ so as to minimize the estimated mean-squared error $ L= \frac{1}{N_D}\sum_i(y_i-\hat{Q}_\omega(x_i,a_i))^2$ using gradient descent.
  \State Update policy gradient using the sample gradient $\nabla_\theta \rho \approx \frac{1}{N_D}\sum_{i} \nabla_\theta \pi(x_i,a_i) \hat{Q}_\omega(x_i,a_i) $
\State $\theta_{k+1}  =  \theta_{k} + \frac{1}{k}\nabla_\theta \rho$
    \State Every C steps, reset $\hat{Q}' \gets \hat{Q}$,  $\pi' \gets \pi$, $ \omega'\gets \omega$ and $\theta' \gets \theta$. 
      \EndFor
\EndFor


\end{algorithmic}
\end{algorithm}









\section{Application}

In this section,  we test our model with a set of intraday trading data from six highly traded and correlated stocks: Apple (AAPL), Google (GOOG), IBM (IBM), ATT (T), Verizon (VZ),  and Exxon Mobil (XOM) during the week of September 5 to 8, 2017.  Using the standard statistical estimation methodology we calibrate the model \eqref{dynamics}, the expected mean returns of these stocks in September are
\bea
\mu_1 = -3.53\times 10^{-6} ,\quad \mu_2 = -2.16\times 10^{-7}\\
\mu_3 = -1.49\times 10^{-6} ,\quad \mu_4 = -1.06\times 10^{-5}\\
\mu_5 = -7.66\times 10^{-6} ,\quad \mu_6 = 5.94\times 10^{-6},
\eea
where $i=1, 2, ...,6$ represent AAPL, GOOG, IBM, T, VZ, and XOM respectively. Their covariance matrix $(\sigma_{ij})_{1\leq i,j\leq 6}$ for September   is
\bea
&\left[ \begin{array}{llllll}
6.5 & 0.17 & 0.03 & -0.015 & 0.26 & 0.15\\ 
0.17 & 6.9 & -0.088 & 0.15 & -0.012 & 0.045\\
0.03 & -0.088 & 4.46 & 0.007 & 0.065 & 0.37\\
-0.015& 0.15 &0.007 &6.98& 0.011& 0.019\\
0.26&-0.12&0.065&0.011&6.46&0.13\\
0.15& 0.045& 0.37&0.019& 0.13 &5.7
\end{array}
\right]\\
&\quad\times 10^{-8}.
\eea 

 For each of these stock we have a threshold $M_i$ that we can traded at once without been detected. In fact, $M_i$ represents the maximum number of shares we can sell or buy at the given traded for the $i$-th stock. Consequently the action $a_{i,k} \in [-M_i, M_i]$.  In this particular case we have
\bea
M_1 =200, \quad M_2 =50\\
M_3 = 200, \quad M_4 = 500\\
M_5 = 500, \quad M_6 = 200.
